        const int SuffixLength = 37;

        var name = Path.GetFileName(destination);
        var keep = MaxFileNameLength - SuffixLength;

        if (name.Length > keep)
        {
            keep -= char.IsHighSurrogate(name[keep - 1]) ? 1 : 0;
            name = name[..keep];
        }

        return Path.Combine(Path.GetDirectoryName(destination)!, name + "." + Guid.NewGuid().ToString("N") + ".tmp");
