        /// <summary>The stream being read (owned by the caller).</summary>
        private readonly Stream _source;

        /// <summary>The number of bytes the stream must yield.</summary>
        private readonly long _length;

        /// <summary>The bytes still owed before the declared length is reached.</summary>
        private long _remaining;

        /// <summary>Whether the source has been confirmed to end at the declared length.</summary>
        private bool _endVerified;

        /// <summary>Wraps <paramref name="source"/> to yield exactly <paramref name="length"/> bytes.</summary>
        public ExactLengthStream(Stream source, long length)
        {
            _source = source;
            _length = length;
            _remaining = length;
        }

        public override bool CanRead => true;

        public override bool CanSeek => false;

        public override bool CanWrite => false;

        public override long Length => throw new NotSupportedException();

        public override long Position
        {
            get => throw new NotSupportedException();
            set => throw new NotSupportedException();
        }

        public override int Read(byte[] buffer, int offset, int count) =>
            Read(buffer.AsSpan(offset, count));

        public override int Read(Span<byte> buffer)
        {
            if (buffer.IsEmpty)
            {
                return 0;
            }

            if (_remaining == 0)
            {
                if (!_endVerified)
                {
                    Span<byte> probe = stackalloc byte[1];
                    VerifyEnd(_source.Read(probe));
                }

                return 0;
            }

            var read = Consume(_source.Read(buffer[..Allowed(buffer.Length)]));

            // Check the end before handing on the bytes that reach the declared length (see WithExactLength)
            if (_remaining == 0)
            {
                Span<byte> probe = stackalloc byte[1];
                VerifyEnd(_source.Read(probe));
            }

            return read;
        }

        public override System.Threading.Tasks.Task<int> ReadAsync(
            byte[] buffer,
            int offset,
            int count,
            System.Threading.CancellationToken cancellationToken
        ) => ReadAsync(buffer.AsMemory(offset, count), cancellationToken).AsTask();

        public override async System.Threading.Tasks.ValueTask<int> ReadAsync(
            Memory<byte> buffer,
            System.Threading.CancellationToken cancellationToken = default
        )
        {
            if (buffer.IsEmpty)
            {
                return 0;
            }

            if (_remaining == 0)
            {
                if (!_endVerified)
                {
                    var probe = new byte[1];
                    VerifyEnd(await _source.ReadAsync(probe, cancellationToken).ConfigureAwait(false));
                }

                return 0;
            }

            var read = Consume(
                await _source.ReadAsync(buffer[..Allowed(buffer.Length)], cancellationToken).ConfigureAwait(false)
            );

            // Check the end before handing on the bytes that reach the declared length (see WithExactLength)
            if (_remaining == 0)
            {
                var probe = new byte[1];
                VerifyEnd(await _source.ReadAsync(probe, cancellationToken).ConfigureAwait(false));
            }

            return read;
        }

        /// <summary>Caps a read at the bytes still owed, so the source is never read past the declared length.</summary>
        private int Allowed(int requested) => (int)Math.Min(requested, _remaining);

        /// <summary>Counts a read against the declared length; a source that ends early is rejected.</summary>
        private int Consume(int read)
        {
            if (read == 0)
            {
                throw new ArgumentException(
                    $"The stream ended after {_length - _remaining} bytes, before the {_length} bytes given as its length.",
                    "length"
                );
            }

            _remaining -= read;
            return read;
        }

        /// <summary>Checks the read past the declared length; a source that still has data is rejected.</summary>
        private void VerifyEnd(int read)
        {
            if (read != 0)
            {
                throw new ArgumentException(
                    $"The stream has more data than the {_length} bytes given as its length.",
                    "length"
                );
            }

            _endVerified = true;
        }

        public override void Flush() { }

        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();

        public override void SetLength(long value) => throw new NotSupportedException();

        public override void Write(byte[] buffer, int offset, int count) =>
            throw new NotSupportedException();
    }
}

/// <summary>Converts a raw value read from the database into a target CLR type, including the types <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/> cannot reach on its own.</summary>
/// <remarks>
/// <para>
/// <c>Convert.ChangeType</c> only converts types that implement <see cref="IConvertible"/>. <see cref="TimeSpan"/>,
/// <see cref="Guid"/>, <see cref="DateTimeOffset"/>, <see cref="DateOnly"/> and <see cref="TimeOnly"/> do not, so a driver
/// that hands such a column back as text makes it throw <see cref="InvalidCastException"/> - which is what SQLite does for
/// every one of them, since it stores them as TEXT. Those types are parsed from the string instead, with the invariant culture.
/// SQL Server returns them already typed, so they take the pass-through above and never reach the parsing.
/// Binary (<c>byte[]</c>) is the same case with Base64 as its text shape, so a binary value object can be created from a
/// CSV field or a spreadsheet cell through <c>TryCreateFrom</c> / <c>CreateFrom</c> like every other value type.
/// </para>
/// <para>
/// Two more shapes <c>ChangeType</c> cannot reach are handled before it: an enum, from a member name or a number, and the
/// <see cref="DateOnly"/> / <see cref="TimeOnly"/> a driver hands back as a <see cref="DateTime"/> / <see cref="TimeSpan"/>
/// (SQL Server reads date and time columns that way).
/// </para>
/// <para>
/// <see cref="ConvertRaw"/> also reads a stored <see cref="DateTime"/> and <see cref="Guid"/> the way the SQLite driver's typed
/// getters do: date and time text that carries an offset is converted to UTC (text without one stays Unspecified), and a 16-byte
/// blob is a Guid. The generated repositories read most rows through those getters, so a value read through this conversion -
/// a value object column, a <c>Query()</c> row, a raw SQL result - comes out the same as the same row read by <c>GetByIdAsync</c>.
/// </para>
/// <para>
/// This is the single conversion shared by value object rewrapping, raw SQL scalars, raw SQL projection properties and the
/// SQLite engine's own column coercion (<c>EntitySaveMetadata.CoerceScalar</c>), so a value object column and a plain column
/// read the same text the same way.
/// </para>
/// <para>
/// <see cref="ConvertInput"/> is the same conversion for a value that did not come from a database - a spreadsheet cell, a CSV
/// field, a form field - where the culture belongs to the caller and numeric text carries the group separators a person typed.
/// Both entry points share one body, so the list of types they can reach cannot drift apart.
/// </para>
/// </remarks>
internal static class RawValueConverter
{
    /// <summary>Converts the raw value to the target type (a nullable target is judged by its underlying type); a value already of that type is returned as is.</summary>
    /// <param name="raw">The value the driver returned (never <c>null</c>: the callers map null and <c>DBNull</c> before this point).</param>
    /// <param name="targetType">The type to convert to.</param>
    /// <exception cref="InvalidCastException">No conversion exists between the two types.</exception>
    /// <exception cref="FormatException">The text does not have the shape the target type requires.</exception>
    /// <exception cref="OverflowException">The value does not fit the target type.</exception>
    public static object ConvertRaw(object raw, Type targetType) =>
        ConvertCore(raw, targetType, CultureInfo.InvariantCulture, fromDatabase: true);

    /// <summary>Converts a value that came from outside the database - a spreadsheet cell, a CSV field, a form field - to the target type.</summary>
    /// <remarks>
    /// Two things separate this from <see cref="ConvertRaw"/>. The culture is the one the caller passes, because the text was
    /// written by a person or by an application that formatted it for one. And numeric text is parsed with group separators
    /// allowed, because a spreadsheet hands back "1,234" for a column formatted that way while
    /// <see cref="System.Convert.ChangeType(object, Type, IFormatProvider)"/> rejects it outright. An integral target still
    /// rejects a decimal point, so "1,234.5" does not quietly become an int.
    /// </remarks>
    /// <param name="raw">The value read from the source (never <c>null</c>: the callers map the empty cases before this point).</param>
    /// <param name="targetType">The type to convert to.</param>
    /// <param name="provider">The culture the text is written in; <c>null</c> uses the invariant culture.</param>
    /// <exception cref="InvalidCastException">No conversion exists between the two types.</exception>
    /// <exception cref="FormatException">The text does not have the shape the target type requires.</exception>
    /// <exception cref="OverflowException">The value does not fit the target type.</exception>
    public static object ConvertInput(object raw, Type targetType, IFormatProvider? provider) =>
        ConvertCore(raw, targetType, provider ?? CultureInfo.InvariantCulture, fromDatabase: false);

    /// <summary>Body shared by <see cref="ConvertRaw"/> and <see cref="ConvertInput"/>; the two differ in the culture, in whether numeric text may carry group separators, and in reading a stored date and time or Guid the way the driver does.</summary>
    private static object ConvertCore(
        object raw,
        Type targetType,
        IFormatProvider provider,
        bool fromDatabase
    )
    {
        var underlying = Nullable.GetUnderlyingType(targetType) ?? targetType;

        if (underlying.IsInstanceOfType(raw))
        {
            return raw;
        }

        // Before the numeric parse below, which would hand back the underlying integer: Type.GetTypeCode reports an enum
        // as its underlying type, and ChangeType cannot produce an enum at all
        if (underlying.IsEnum)
        {
            return ConvertEnum(raw, underlying, provider);
        }

        // A driver reads a date column as a DateTime and a time column as a TimeSpan (SQL Server does both)
        if (underlying == typeof(DateOnly) && raw is DateTime dateTime)
        {
            return ToDateOnly(dateTime);
        }

        if (underlying == typeof(TimeOnly) && raw is TimeSpan timeSpan)
        {
            return ToTimeOnly(timeSpan);
        }

        // A value the database stored as text or a blob is read the way the SQLite driver's typed getters read it, so a row read
        // through this conversion matches the same row read through GetDateTime / GetGuid: a date and time that carries an
        // offset is converted to UTC (one without stays Unspecified), and a 16-byte blob is a Guid
        if (fromDatabase)
        {
            if (underlying == typeof(DateTime) && raw is string dateTimeText)
            {
                return DateTime.Parse(dateTimeText, provider, System.Globalization.DateTimeStyles.AdjustToUniversal);
            }

            if (underlying == typeof(Guid) && raw is byte[] { Length: 16 } guidBytes)
            {
                return new Guid(guidBytes);
            }
        }

        // Text is the only shape these types can arrive in, and none of them implements IConvertible,
        // so leaving them to ChangeType would fail on every value rather than on a malformed one
        if (raw is string text && !typeof(IConvertible).IsAssignableFrom(underlying))
        {
            if (underlying == typeof(Guid))
            {
                return Guid.Parse(text);
            }

            if (underlying == typeof(TimeSpan))
            {
                return ParseTimeSpan(text, provider);
            }

            if (underlying == typeof(DateTimeOffset))
            {
                return DateTimeOffset.Parse(text, provider, System.Globalization.DateTimeStyles.RoundtripKind);
            }

            if (underlying == typeof(DateOnly))
            {
                return DateOnly.Parse(text, provider);
            }

            if (underlying == typeof(TimeOnly))
            {
                return TimeOnly.Parse(text, provider);
            }

            if (underlying == typeof(byte[]))
            {
                // Base64 is the text shape of binary here - the same notation the edit models accept,
                // so a CSV/spreadsheet import and the screen read binary input the same way
                return Convert.FromBase64String(text);
            }
        }

        if (!fromDatabase && raw is string number && ParseNumber(number, underlying, provider) is { } parsed)
        {
            return parsed;
        }

        return Convert.ChangeType(raw, underlying, provider);
    }

    /// <summary>Converts a raw value to an enum: text by member name or number, anything else through the underlying integer type.</summary>
    /// <remarks>
    /// A number that names no member is accepted, the same as a C# cast. Text that
    /// is neither a member name nor a number throws <see cref="FormatException"/> rather than the <see cref="ArgumentException"/>
    /// <see cref="Enum.Parse(Type, string)"/> would, so the callers report it like any other malformed value.
    /// </remarks>
    private static object ConvertEnum(object raw, Type enumType, IFormatProvider provider)
    {
        if (raw is string text)
        {
            return Enum.TryParse(enumType, text, ignoreCase: false, out var parsed)
                ? parsed!
                : throw new FormatException($"'{text}' is neither a member name nor a number of {enumType.Name}.");
        }

        return Enum.ToObject(enumType, Convert.ChangeType(raw, Enum.GetUnderlyingType(enumType), provider));
    }

    /// <summary>Converts a DateTime to a DateOnly, refusing one that carries a time of day.</summary>
    /// <remarks>
    /// A date column comes back at midnight, so the time is the part a date cannot hold. A value with a time of day was read
    /// from a column that is not a date - a datetime2 projected into a DateOnly property, say - and dropping the time there
    /// would change the value without a word, so it fails like any other value that does not fit its target.
    /// </remarks>
    private static DateOnly ToDateOnly(DateTime value) =>
        value.TimeOfDay == TimeSpan.Zero
            ? DateOnly.FromDateTime(value)
            : throw new InvalidCastException($"The DateTime value {value:O} carries a time of day and cannot be read as a DateOnly.");

    /// <summary>Converts a TimeSpan to a TimeOnly, refusing one outside a single day.</summary>
    /// <remarks>
    /// A time column comes back as a span within one day. A negative span or one of a day or more does not name a time of day
    /// (<see cref="TimeOnly.FromTimeSpan"/> would throw <see cref="ArgumentOutOfRangeException"/>), so it fails as a value
    /// that does not fit its target.
    /// </remarks>
    private static TimeOnly ToTimeOnly(TimeSpan value) =>
        value >= TimeSpan.Zero && value < TimeSpan.FromDays(1)
            ? TimeOnly.FromTimeSpan(value)
            : throw new OverflowException($"The TimeSpan value {value} is not a time of day and cannot be read as a TimeOnly.");

    /// <summary>Parses numeric text with group separators allowed, or returns null when the target is not a number.</summary>
    /// <remarks>
    /// An integral target takes <see cref="NumberStyles.Integer"/> rather than <see cref="NumberStyles.Number"/> on purpose:
    /// the latter also allows a decimal point, which would let "1,234.5" through as an int. A fractional target keeps the
    /// exponent form that <c>ChangeType</c> would have accepted.
    /// </remarks>
    private static object? ParseNumber(string text, Type underlying, IFormatProvider provider)
    {
        const NumberStyles Integral = NumberStyles.Integer | NumberStyles.AllowThousands;
        const NumberStyles Fractional = NumberStyles.Float | NumberStyles.AllowThousands;

        return Type.GetTypeCode(underlying) switch
        {
            TypeCode.Byte => byte.Parse(text, Integral, provider),
            TypeCode.SByte => sbyte.Parse(text, Integral, provider),
            TypeCode.Int16 => short.Parse(text, Integral, provider),
            TypeCode.UInt16 => ushort.Parse(text, Integral, provider),
            TypeCode.Int32 => int.Parse(text, Integral, provider),
            TypeCode.UInt32 => uint.Parse(text, Integral, provider),
            TypeCode.Int64 => long.Parse(text, Integral, provider),
            TypeCode.UInt64 => ulong.Parse(text, Integral, provider),
            TypeCode.Single => float.Parse(text, Fractional, provider),
            TypeCode.Double => double.Parse(text, Fractional, provider),
            TypeCode.Decimal => decimal.Parse(text, Fractional, provider),
            _ => null,
        };
    }

    /// <summary>Parses a <see cref="TimeSpan"/> stored as text.</summary>
    /// <remarks>
    /// The round-trip format "c" ([-][d.]hh:mm:ss[.fffffff]) is what the SQLite provider writes, and it also accepts the
    /// forms that round-trip shorter values ("01:00:00", "1.02:03:04", "10:20:30.1234567"). The fallback covers text that
    /// something other than this library stored (a hand-written INSERT such as "1:2:3"), which is the same set the plain
    /// column path has always accepted, so both paths read the same rows.
    /// </remarks>
    private static TimeSpan ParseTimeSpan(string text, IFormatProvider provider) =>
        TimeSpan.TryParseExact(text, "c", CultureInfo.InvariantCulture, out var roundTripped)
            ? roundTripped
            : TimeSpan.Parse(text, provider);
}

/// <summary>Change state of an entity or EditModel.</summary>
public enum RowState
{
    /// <summary>Marked for insert (new).</summary>
    Added,

    /// <summary>Unchanged (already persisted).</summary>
    Unchanged,

    /// <summary>Marked for update.</summary>
    Updated,

    /// <summary>Marked for removal.</summary>
    Removed,
}

/// <summary>Base class that holds the change tracking state (RowState) of an entity.</summary>
public abstract class EntityBaseCore
{
    /// <summary>Change tracking state of this entity. Defaults to Unchanged; restoring from the database or JSON keeps it Unchanged.</summary>
    public RowState RowState { get; set; } = RowState.Unchanged;

    /// <summary>Gets whether this entity is marked for insert.</summary>
    public bool IsAdded => RowState == RowState.Added;

    /// <summary>Gets whether this entity is marked for update.</summary>
    public bool IsUpdated => RowState == RowState.Updated;

    /// <summary>Gets whether this entity is marked for removal.</summary>
    public bool IsRemoved => RowState == RowState.Removed;

    /// <summary>Gets whether this entity has any change (insert, update, or removal).</summary>
    public bool HasChanges => RowState != RowState.Unchanged;

    /// <summary>Display name of this entity (used for UI labels and so on). Returns <see cref="DefaultDisplayName"/>; substitute display names by replacing GeneratedDisplayNames.Resolve and branching on the class name it receives.</summary>
    public string DisplayName => DefaultDisplayName;

    /// <summary>Default display name. Resolved from the runtime class name through GeneratedDisplayNames.Resolve (no description); entities that carry a table description override this in the derived class.</summary>
    protected virtual string DefaultDisplayName => GeneratedDisplayNames.Resolve(GetType().Name, null);

    /// <summary>Marks this entity for insert (use when a directly constructed entity should be saved).</summary>
    /// <param name="includeChildren">
    /// <c>true</c> to mark the cascade children as well (the child-direction navigations a graph save follows, all the way
    /// down), so a freshly built aggregate can be marked in a single call. The default <c>false</c> marks this entity only.
    /// </param>
    /// <remarks>
    /// Only MarkAdded offers the cascading form. Marking a whole graph for update is ambiguous (the save would rewrite every
    /// row, including the ones nothing touched), and marking a whole graph for removal is what the graph save's
    /// <c>cascadeDelete</c> option already does from the root alone.
    /// </remarks>
    public void MarkAdded(bool includeChildren = false)
    {
        RowState = RowState.Added;

        if (!includeChildren)
        {
            return;
        }

        // Cascade navigations point at children only (parent references are excluded), so the traversal is a tree and terminates
        foreach (var child in EnumerateCascadeChildren())
        {
            child.MarkAdded(true);
        }
    }

    /// <summary>Caches the cascade navigation properties per type (the child-direction navigations a graph save follows).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _cascadeNavigationCache = new();

    /// <summary>Returns the cascade navigation properties of the given type (scanned once per type and cached).</summary>
    internal static PropertyInfo[] GetCascadeNavigations(Type type) =>
        _cascadeNavigationCache.GetOrAdd(
            type,
            static resolvedType =>
                resolvedType
                    .GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property =>
                        property.GetCustomAttribute<NavigationReferenceAttribute>()
                            is { Cascade: true }
                    )
                    .ToArray()
        );

    /// <summary>Enumerates the children reachable through cascade navigations (single references and collections alike; nulls are skipped).</summary>
    /// <remarks>
    /// This is the one description of "which children a graph operation follows", and everything that has to walk the same
    /// shape - marking an aggregate, saving it, journaling it for a sync run - reads it from here rather than repeating the
    /// attribute scan. Cascade navigations point at children only (parent references are excluded), so the traversal is a
    /// tree and terminates.
    /// </remarks>
    public IEnumerable<EntityBaseCore> EnumerateCascadeChildren()
    {
        foreach (var navigation in GetCascadeNavigations(GetType()))
        {
            var value = navigation.GetValue(this);

            if (value is EntityBaseCore child)
            {
                yield return child;
            }
            else if (value is IEnumerable<EntityBaseCore> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        yield return item;
                    }
                }
            }
        }
    }

    /// <summary>Marks this entity for removal (it stays in its collection until a graph save deletes it; a successful save then takes it out of a kept parent's collection, and it stays Removed).</summary>
    public void MarkRemoved() => RowState = RowState.Removed;

    /// <summary>Marks this entity as Unchanged (already persisted).</summary>
    public void MarkUnchanged() => RowState = RowState.Unchanged;

    /// <summary>Marks this entity for update only when it is currently Unchanged.</summary>
    public void MarkUpdated()
    {
        if (RowState == RowState.Unchanged)
        {
            RowState = RowState.Updated;
        }
    }

    // ---- Value comparison, hashing, and JSON output ----

    /// <summary>Caches the "value properties" per type (the public get/set properties carrying a <see cref="ColumnAttribute"/>).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _valuePropertyCache = new();

    /// <summary>Returns the value properties of the given type (scanned once per type and cached).</summary>
    /// <remarks>A property is a column only when it carries <see cref="ColumnAttribute"/>, which the generator puts on every column property. Anything else a partial declaration adds - navigations, RowState, and members added to the extension surface - is therefore not a column. Add <see cref="ColumnAttribute"/> with the name of a real column to opt a handwritten property in.</remarks>
    private static PropertyInfo[] GetValueProperties(Type type) =>
        _valuePropertyCache.GetOrAdd(
            type,
            static resolvedType =>
                resolvedType
                    .GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property =>
                        property.CanRead
                        && property.CanWrite
                        && Attribute.IsDefined(property, typeof(ColumnAttribute))
                    )
                    .ToArray()
        );

    /// <summary>Determines whether all column values match those of another entity (RowState and navigations are excluded from the comparison).</summary>
    /// <remarks>The comparison reads each column through reflection (the property list itself is cached per type). That is meant for change detection and assertions, not for a hot path — write the comparison out by hand where one is called for.</remarks>
    public bool HasSameValues(EntityBaseCore? other)
    {
        if (other is null)
        {
            return false;
        }

        if (ReferenceEquals(this, other))
        {
            return true;
        }

        var type = GetType();
        if (other.GetType() != type)
        {
            return false;
        }

        foreach (var property in GetValueProperties(type))
        {
            // Compare arrays such as byte[] structurally (element by element).
            if (
                !StructuralComparisons.StructuralEqualityComparer.Equals(
                    property.GetValue(this),
                    property.GetValue(other)
                )
            )
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Returns a value-based hash code computed from the column values (RowState and navigations are excluded).</summary>
    /// <remarks>Two entities for which HasSameValues is true always return the same value. Since the object is mutable, do not modify it while using it as a dictionary key. Like HasSameValues, it reads the columns through reflection and is not meant for a hot path.</remarks>
    public int GetValueHashCode()
    {
        var type = GetType();
        var hash = new HashCode();
        hash.Add(type);
        foreach (var property in GetValueProperties(type))
        {
            var value = property.GetValue(this);
            // Use a structural hash for arrays such as byte[].
            hash.Add(
                value is null
                    ? 0
                    : StructuralComparisons.StructuralEqualityComparer.GetHashCode(value)
            );
        }

        return hash.ToHashCode();
    }

    /// <summary>Serialization options shared by JSON output (ToJson) and cloning (Clone). Reused so that type-metadata caching takes effect.</summary>
    /// <remarks>Only public get/set properties are included. Any accidental cycle is nulled out via IgnoreCycles to avoid exceptions (with the [JsonIgnore] configuration there is no cycle, so this is a no-op).</remarks>
    private static readonly JsonSerializerOptions _jsonOptions = new()
    {
        IgnoreReadOnlyProperties = true,
        ReferenceHandler = ReferenceHandler.IgnoreCycles,
    };

    /// <summary>Options for indented output (writeIndented=true). Kept as a separate instance because WriteIndented cannot be changed after first use.</summary>
    private static readonly JsonSerializerOptions _jsonOptionsIndented = new()
    {
        IgnoreReadOnlyProperties = true,
        ReferenceHandler = ReferenceHandler.IgnoreCycles,
        WriteIndented = true,
    };

    /// <summary>Serializes this entity to a JSON string (used for passing data to a web API and so on).</summary>
    /// <remarks>
    /// Only public get/set properties are included (get-only derived flags such as IsAdded are not emitted; RowState is emitted).
    /// Child navigations are included; with the default configuration (IncludeJsonIgnoreOnParentNavigation) parent-reference
    /// navigations carry [JsonIgnore] and are left out. Without the attribute they are emitted, and a cycle back to this
    /// entity is nulled out by IgnoreCycles instead.
    /// </remarks>
    public string ToJson(bool writeIndented = false) =>
        JsonSerializer.Serialize(
            this,
            GetType(),
            writeIndented ? _jsonOptionsIndented : _jsonOptions
        );

    /// <summary>Creates a deep clone of this entity (via a JSON round-trip).</summary>
    /// <remarks>
    /// Values, RowState, and child navigations are copied. With the default configuration (IncludeJsonIgnoreOnParentNavigation)
    /// parent-reference navigations are not restored (the clone does not point to a parent); without the attribute, restoring
    /// them depends on how IgnoreCycles serialized the graph.
    /// To insert it as a separate record, reassign the primary key or call MarkAdded() after cloning. The returned instance has the same concrete type as the original.
    /// </remarks>
    public EntityBaseCore Clone()
    {
        var type = GetType();
        var json = JsonSerializer.Serialize(this, type, _jsonOptions);
        return (EntityBaseCore)JsonSerializer.Deserialize(json, type, _jsonOptions)!;
    }
}

/// <summary>Resolves default display names for generated members (entities, edit model properties, and value objects). Replacing the resolver at app startup applies to every generated display name.</summary>
public static class GeneratedDisplayNames
{
    /// <summary>Resolves a display name from the member name and the column/table description (null when unset). The default prefers the description and falls back to the member name. Replace with (name, _) =&gt; name to ignore descriptions.</summary>
    public static Func<string, string?, string> Resolve { get; set; } =
        static (memberName, description) => description ?? memberName;
}

/// <summary>The order every backend's graph save runs its operations (and fires its save hooks) in.</summary>
/// <remarks>
/// <para>
/// A graph save that deletes no row runs in graph order: it walks each root, and a new or updated row is written before its
/// children. A save that deletes rows runs in three stages:
/// </para>
/// <list type="number">
///   <item>the new and updated rows, walking each root in graph order and leaving out the deleted rows and the held-back rows,
///     with the rows below them;</item>
///   <item>the deleted rows, in the order the walk reached them, each deleting its subtree children first;</item>
///   <item>the held-back rows, in the order the walk reached them, each with the rows below it.</item>
/// </list>
/// <para>
/// A row is held back when it takes a value a row the same save deletes still holds: a new row that takes the primary key or
/// a unique value of a deleted row, or an updated row that takes a unique value (other than the primary key) of a deleted
/// row. Writing it before the deletion would be refused by the database. The other writes come before the deletions, so a
/// row that moves away from a deleted parent is updated first, whatever order the roots come in, and the parent can then be
/// deleted (a cascading deletion no longer takes the moved row with it).
/// </para>
/// <para>
/// Values are matched in the form <see cref="IncludeKeys.Normalize"/> gives them, text without regard to case (a collation that
/// ignores case sees the same value); a value with a null part matches nothing. The QuickER repositories, EF Core and the
/// in-memory repository share this order, so their save hooks fire in the same sequence; EF Core still orders the statements
/// of its single SaveChanges itself.
/// </para>
/// <para>
/// A walk starts from each of <see cref="StartingPoints"/> in turn and skips a child for which <see cref="Defers"/> returns
/// <c>true</c>: that child starts a later stage of its own, or (a deleted row below a held-back row) was deleted in the second
/// stage already.
/// </para>
/// </remarks>
internal sealed class GraphSaveOrder
{
    /// <summary>Caches, per entity type, the property groups whose values must be unique (the primary key first).</summary>
    private static readonly ConcurrentDictionary<Type, UniqueGroups> _uniqueGroups = new();

    private readonly List<EntityBaseCore> _deletions = [];
    private readonly List<EntityBaseCore> _heldBack = [];
    private readonly HashSet<EntityBaseCore> _deferred = new(ReferenceEqualityComparer.Instance);
    private readonly List<EntityBaseCore> _startingPoints = [];

    private GraphSaveOrder() { }

    /// <summary>
    /// Gets where the walks start, in the order they run: the roots that are neither deleted nor held back, then
    /// <see cref="Deletions"/>, then <see cref="HeldBack"/>.
    /// </summary>
    public IReadOnlyList<EntityBaseCore> StartingPoints => _startingPoints;

    /// <summary>Gets the deleted rows the second stage starts from, in the order the walk reached them.</summary>
    public IReadOnlyList<EntityBaseCore> Deletions => _deletions;

    /// <summary>Gets the held-back rows the third stage starts from, in the order the walk reached them (each is saved with the rows below it).</summary>
    public IReadOnlyList<EntityBaseCore> HeldBack => _heldBack;

    /// <summary>Plans one save over <paramref name="roots"/>; null when the save deletes no row (it then runs in graph order).</summary>
    /// <param name="roots">The roots the save walks.</param>
    /// <param name="cascadeSave">Whether the save walks the cascade children.</param>
    /// <param name="cascadeDelete">Whether deleting a row deletes the rows below it.</param>
    public static GraphSaveOrder? For(IEnumerable<EntityBaseCore> roots, bool cascadeSave, bool cascadeDelete)
    {
        var rootList = roots.ToList();
        var deleted = new HashSet<UniqueValue>();
        var deletes = false;

        foreach (var root in rootList)
        {
            deletes |= CollectDeleted(root, cascadeSave, cascadeDelete, deleted);
        }

        if (!deletes)
        {
            return null;
        }

        var order = new GraphSaveOrder();

        foreach (var root in rootList)
        {
            order.Plan(root, cascadeSave, deleted, belowHeldBack: false);
        }

        order._startingPoints.AddRange(rootList.Where(root => !order._deferred.Contains(root)));
        order._startingPoints.AddRange(order._deletions);
        order._startingPoints.AddRange(order._heldBack);
        return order;
    }

    /// <summary>
    /// Returns whether the walk leaves <paramref name="entity"/> and the rows below it out (it starts a later stage, or was
    /// deleted in the second stage already).
    /// </summary>
    /// <param name="entity">A child the walk reached.</param>
    public bool Defers(EntityBaseCore entity) => _deferred.Contains(entity);

    /// <summary>Sorts a row the walk reaches into the stage that writes it.</summary>
    private void Plan(
        EntityBaseCore entity,
        bool cascadeSave,
        HashSet<UniqueValue> deleted,
        bool belowHeldBack
    )
    {
        if (entity.IsRemoved)
        {
            _deletions.Add(entity);
            _deferred.Add(entity);
            return;
        }

        if (!belowHeldBack && TakesDeletedValue(entity, deleted))
        {
            _heldBack.Add(entity);
            _deferred.Add(entity);
            belowHeldBack = true;
        }

        if (!cascadeSave)
        {
            return;
        }

        foreach (var child in entity.EnumerateCascadeChildren())
        {
            Plan(child, cascadeSave, deleted, belowHeldBack);
        }
    }

    /// <summary>
    /// Returns whether a new row takes the primary key or a unique value of a deleted row, or an updated row takes a unique
    /// value (other than the primary key) of one.
    /// </summary>
    private static bool TakesDeletedValue(EntityBaseCore entity, HashSet<UniqueValue> deleted)
    {
        if (deleted.Count == 0)
        {
            return false;
        }

        if (entity.IsAdded)
        {
            return ValuesOf(entity, includeKey: true).Any(deleted.Contains);
        }

        return entity.IsUpdated && ValuesOf(entity, includeKey: false).Any(deleted.Contains);
    }

    /// <summary>
    /// Collects the values of the rows the save deletes (a deleted row's subtree too, when deleting cascades) and returns
    /// whether the walk from <paramref name="entity"/> reaches a deleted row.
    /// </summary>
    private static bool CollectDeleted(
        EntityBaseCore entity,
        bool cascadeSave,
        bool cascadeDelete,
        HashSet<UniqueValue> deleted
    )
    {
        if (entity.IsRemoved)
        {
            AddValues(entity, deleted);

            if (cascadeDelete)
            {
                foreach (var child in entity.EnumerateCascadeChildren())
                {
                    CollectSubtree(child, deleted);
                }
            }

            return true;
        }

        var deletes = false;

        if (cascadeSave)
        {
            foreach (var child in entity.EnumerateCascadeChildren())
            {
                deletes |= CollectDeleted(child, true, cascadeDelete, deleted);
            }
        }

        return deletes;
    }

    /// <summary>Collects the values of a subtree a deletion takes with it (a new row there has no stored row to free).</summary>
    private static void CollectSubtree(EntityBaseCore entity, HashSet<UniqueValue> deleted)
    {
        if (!entity.IsAdded)
        {
            AddValues(entity, deleted);
        }

        foreach (var child in entity.EnumerateCascadeChildren())
        {
            CollectSubtree(child, deleted);
        }
    }

    private static void AddValues(EntityBaseCore entity, HashSet<UniqueValue> deleted)
    {
        foreach (var value in ValuesOf(entity, includeKey: true))
        {
            deleted.Add(value);
        }
    }

    /// <summary>Returns the entity's unique values, with or without the primary key (a group with a null part is left out).</summary>
    private static IEnumerable<UniqueValue> ValuesOf(EntityBaseCore entity, bool includeKey)
    {
        var type = entity.GetType();
        var resolved = _uniqueGroups.GetOrAdd(type, ResolveUniqueGroups);
        var groups = resolved.Groups;

        for (var index = includeKey || !resolved.FirstIsKey ? 0 : 1; index < groups.Length; index++)
        {
            var properties = groups[index];
            var parts = new object[properties.Length];
            var complete = true;

            for (var part = 0; part < properties.Length; part++)
            {
                if (IncludeKeys.Normalize(properties[part].GetValue(entity)) is not { } value)
                {
                    complete = false;
                    break;
                }

                parts[part] = value;
            }

            if (complete)
            {
                yield return new UniqueValue(type, index, parts);
            }
        }
    }

    /// <summary>Resolves the primary key ([Key]) and the [UniqueConstraint] groups of an entity type.</summary>
    private static UniqueGroups ResolveUniqueGroups(Type type)
    {
        var groups = new List<PropertyInfo[]>();
        var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
        var key = properties.FirstOrDefault(property => property.GetCustomAttribute<KeyAttribute>() is not null);

        if (key is not null)
        {
            groups.Add([key]);
        }

        foreach (var constraint in type.GetCustomAttributes<UniqueConstraintAttribute>())
        {
            var members = constraint
                .PropertyNames.Select(name => properties.FirstOrDefault(property => property.Name == name))
                .ToArray();

            if (members.Length > 0 && members.All(member => member is not null))
            {
                groups.Add(members!);
            }
        }

        return new UniqueGroups([.. groups], key is not null);
    }

    /// <summary>The property groups of an entity type whose values must be unique, and whether the first is the primary key.</summary>
    private sealed class UniqueGroups(PropertyInfo[][] groups, bool firstIsKey)
    {
        public PropertyInfo[][] Groups { get; } = groups;

        public bool FirstIsKey { get; } = firstIsKey;
    }

    /// <summary>One unique value of a row: the entity type, the property group and the normalized values.</summary>
    private sealed class UniqueValue(Type type, int group, object[] parts) : IEquatable<UniqueValue>
    {
        public bool Equals(UniqueValue? other)
        {
            if (other is null || other.Type != Type || other.Group != Group || other.Parts.Length != Parts.Length)
            {
                return false;
            }

            for (var index = 0; index < Parts.Length; index++)
            {
                if (!PartsEqual(Parts[index], other.Parts[index]))
                {
                    return false;
                }
            }

            return true;
        }

        public override bool Equals(object? obj) => Equals(obj as UniqueValue);

        public override int GetHashCode()
        {
            var hash = new HashCode();
            hash.Add(Type);
            hash.Add(Group);

            foreach (var part in Parts)
            {
                hash.Add(part is string text ? StringComparer.OrdinalIgnoreCase.GetHashCode(text) : part.GetHashCode());
            }

            return hash.ToHashCode();
        }

        private Type Type { get; } = type;

        private int Group { get; } = group;

        private object[] Parts { get; } = parts;

        private static bool PartsEqual(object left, object right) =>
            left is string leftText && right is string rightText
                ? string.Equals(leftText, rightText, StringComparison.OrdinalIgnoreCase)
                : left.Equals(right);
    }
}

/// <summary>Settles the cascade collections of a graph after a successful save.</summary>
internal static class CascadeCollections
{
    /// <summary>Caches the <c>ICollection&lt;T&gt;.Remove</c> method per collection type.</summary>
    private static readonly ConcurrentDictionary<Type, MethodInfo?> _removeMethods = new();

    /// <summary>
    /// Takes the children the save deleted out of <paramref name="parent"/>'s cascade collections.
    /// </summary>
    /// <remarks>
    /// A child marked <see cref="RowState.Removed"/> leaves the collection of a parent the save kept, and stays
    /// <c>Removed</c> itself, so code that held on to it can still tell it was deleted; leaving it in the collection would make
    /// the next save of the same graph delete it again. A child a save hook skipped (<paramref name="isSkipped"/>) was not
    /// deleted, so it stays. A single cascade child is not touched: it has no collection to leave, so it stays on its
    /// navigation, still <c>Removed</c>, as an edit model's does. Call it for a parent the save kept; the children of a
    /// deleted parent went with it.
    /// </remarks>
    /// <param name="parent">A saved entity that was not deleted.</param>
    /// <param name="isSkipped">Whether a save hook skipped the child, so that it was not deleted.</param>
    public static void RemoveDeletedChildren(EntityBaseCore parent, Func<EntityBaseCore, bool> isSkipped)
    {
        foreach (var navigation in EntityBaseCore.GetCascadeNavigations(parent.GetType()))
        {
            if (navigation.GetValue(parent) is not IEnumerable<EntityBaseCore> children)
            {
                continue;
            }

            var deleted = children.Where(child => child is not null && child.IsRemoved && !isSkipped(child)).ToList();

            if (deleted.Count == 0)
            {
                continue;
            }

            var remove = _removeMethods.GetOrAdd(
                children.GetType(),
                static type =>
                    type.GetInterfaces()
                        .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(ICollection<>))
                        ?.GetMethod(nameof(ICollection<object>.Remove))
            );

            if (remove is null)
            {
                continue;
            }

            foreach (var child in deleted)
            {
                remove.Invoke(children, new object[] { child });
            }
        }
    }
}

