/// <summary>Base class providing change notification, error management, and helper processing common to edit models.</summary>
/// <remarks>
/// <para>
/// Extension points of a generated edit model (implement only what you need in a partial class of the concrete type;
/// an unimplemented partial method is erased at no cost):
/// </para>
/// <list type="bullet">
/// <item><description>Extra validation: <c>partial void OnValidate();</c></description></item>
/// <item><description>Extra children: <c>protected override void RegisterExtraChildren();</c> (register with AddChild / AddChildren inside)</description></item>
/// <item><description>Input normalization: <c>protected override void CustomizeInputNormalization(string propertyName, string rawValue, ref string normalizedValue);</c></description></item>
/// <item><description>Row editing: <c>partial void OnBeginEdit();</c> / <c>OnEndEdit();</c> / <c>OnCancelEdit();</c></description></item>
/// <item><description>Value change hooks: <c>partial void On{Property}Changing(value) / Changed(value) / Changing(old, new) / Changed(old, new);</c> (one set per column)</description></item>
/// </list>
/// <para>
/// Validation messages and display names are not per-class hooks: replace <see cref="EditModelMessages"/> and
/// <c>GeneratedDisplayNames.Resolve</c>, both of which receive the stable property name so a replacement can switch on
/// <c>nameof</c> and stay compile-safe.
/// </para>
/// </remarks>
public abstract class EditModelBaseCore
    : INotifyPropertyChanged,
        INotifyDataErrorInfo,
        IEditableObject
{
    /// <summary>
    /// Input errors (conversion, value object, OnValidate, and the missing-required-input check) keyed by property name.
    /// A property carries one input error at a time, and the entry remembers whether the required check registered it, so
    /// that check can add and remove its own error without overwriting a conversion error the binding setter produced.
    /// </summary>
    private readonly Dictionary<string, InputError> _errors = new();

    /// <summary>
    /// Duplicate-value error messages keyed by property name, kept in a store of their own so the two kinds never overwrite each other:
    /// a uniqueness check registers and clears only this store, while SetError / ClearErrors touch only <see cref="_errors"/>.
    /// Both stores are merged by <see cref="HasErrors"/>, <see cref="GetErrors"/>, and error collection, so a property can carry a
    /// conversion error and a duplicate-value error at the same time. Each entry holds one slot per check
    /// (<see cref="DuplicateErrorSource"/>), so the check among the siblings and the check against the database neither overwrite
    /// nor clear each other's findings on the same property.
    /// </summary>
    /// <remarks>An entry is removed as soon as both of its slots are empty, which is what keeps <c>Count</c> a valid "are there any" test.</remarks>
    private readonly Dictionary<string, DuplicateErrors> _duplicateErrors = new();

    /// <summary>Counts the times the database check's findings were withdrawn, so a check can tell that what it found has gone stale while it was awaiting.</summary>
    /// <remarks>
    /// It moves on every withdrawal of the <see cref="DuplicateErrorSource.Database"/> findings - an edit of a confirmed value,
    /// a load, a cancelled edit, and the start of another check - whether or not there was anything to clear. Edit models are
    /// not thread-safe, so a plain field is enough.
    /// </remarks>
    private int _databaseCheckGeneration;

    /// <summary>An input error message together with the check that registered it.</summary>
    private readonly record struct InputError(string Message, bool FromRequiredCheck);

    /// <summary>The duplicate-value messages registered on one property, one slot per check that can find them (null where a check found nothing).</summary>
    private readonly record struct DuplicateErrors(string? Siblings, string? Database)
    {
        /// <summary>Whether neither check has anything registered (an entry in this state is dropped from the store).</summary>
        public bool IsEmpty => Siblings is null && Database is null;

        /// <summary>The message the specified check registered (null when it found nothing). An undefined source throws <see cref="ArgumentOutOfRangeException"/>.</summary>
        /// <remarks>
        /// Every slot is named explicitly rather than letting anything that is not one check fall through to the other:
        /// the source travels in from public API (<c>SetDuplicateError</c> and the clears), and a value naming no check
        /// would otherwise be written to - or cleared from - the database slot without a word.
        /// </remarks>
        public string? Of(DuplicateErrorSource source) =>
            source switch
            {
                DuplicateErrorSource.Siblings => Siblings,
                DuplicateErrorSource.Database => Database,
                _ => throw new ArgumentOutOfRangeException(
                    nameof(source),
                    "The duplicate error source must be Siblings or Database."
                ),
            };

        /// <summary>This entry with the specified check's message replaced (null clears that check's slot only). An undefined source throws <see cref="ArgumentOutOfRangeException"/>.</summary>
        public DuplicateErrors With(DuplicateErrorSource source, string? message) =>
            source switch
            {
                DuplicateErrorSource.Siblings => this with { Siblings = message },
                DuplicateErrorSource.Database => this with { Database = message },
                _ => throw new ArgumentOutOfRangeException(
                    nameof(source),
                    "The duplicate error source must be Siblings or Database."
                ),
            };

        /// <summary>The registered messages in a fixed order (the siblings check first), so reporting is deterministic.</summary>
        public IEnumerable<string> Messages()
        {
            if (Siblings is not null)
            {
                yield return Siblings;
            }

            if (Database is not null)
            {
                yield return Database;
            }
        }
    }

    /// <summary>Raised when a property value changes.</summary>
    public event PropertyChangedEventHandler? PropertyChanged;

    /// <summary>Raised when the input errors change.</summary>
    public event EventHandler<DataErrorsChangedEventArgs>? ErrorsChanged;

    /// <summary>Gets a value indicating whether any errors are present (input errors and duplicate-value errors alike).</summary>
    public bool HasErrors => _errors.Count > 0 || _duplicateErrors.Count > 0;

    /// <summary>Number of revert operations in progress (a counter rather than a flag, so a revert started from inside another one cannot clear it early).</summary>
    private int _revertDepth;

    /// <summary>Gets a value indicating whether a revert operation is in progress.</summary>
    protected bool IsReverting => _revertDepth > 0;

    /// <summary>Number of loads in progress (a counter rather than a flag, so a load started from inside a hook cannot clear it early).</summary>
    private int _loadDepth;

    /// <summary>Gets a value indicating whether a load is in progress (confirmed-value changes do not promote the state to Updated while loading).</summary>
    protected bool IsLoading => _loadDepth > 0;

    /// <summary>Gets or sets the change state of this edit model (based on the source entity; confirmed-value changes promote it to Updated).</summary>
    public RowState RowState
    {
        get => _rowState;
        set
        {
            if (_rowState == value)
            {
                return;
            }

            // A new row marked for deletion has no stored row to delete, so the save leaves it out (see IsDiscardedNewRow)
            _removedWhileAdded = value == RowState.Removed && _rowState == RowState.Added;
            _rowState = value;
            OnPropertyChanged(nameof(RowState));
            OnPropertyChanged(nameof(IsAdded));
            OnPropertyChanged(nameof(IsUpdated));
            OnPropertyChanged(nameof(IsRemoved));
            OnPropertyChanged(nameof(HasChanges));
        }
    }

    /// <summary>Backing field for <see cref="RowState"/>.</summary>
    private RowState _rowState = RowState.Unchanged;

    /// <summary>Whether the model went from Added straight to Removed (it stays set only while the model is Removed).</summary>
    private bool _removedWhileAdded;

    /// <summary>
    /// Gets whether this is a new row that was marked for deletion before it was ever saved: it has no stored row, so the
    /// mapper leaves it out of the entity graph and accepting a save takes it out of its collection.
    /// </summary>
    internal bool IsDiscardedNewRow => _removedWhileAdded;

    /// <summary>The entity the mapper last built from this model, and how to read that entity back into it (see the mapper's <c>AcceptSaved</c>).</summary>
    private EntityBaseCore? _appliedEntity;

    /// <summary>Reads <see cref="_appliedEntity"/> back into this model (null when nothing is recorded).</summary>
    private Action? _readBackApplied;

    /// <summary>Gets the entity the mapper last built from this model (null when none is recorded).</summary>
    internal EntityBaseCore? AppliedEntity => _appliedEntity;

    /// <summary>Records the entity the mapper built from this model, so accepting a save can find it again from the model.</summary>
    /// <param name="entity">The entity built from this model.</param>
    /// <param name="readBack">Reads the entity's column values back into this model.</param>
    internal void RememberApplied(EntityBaseCore entity, Action readBack)
    {
        _appliedEntity = entity;
        _readBackApplied = readBack;
    }

    /// <summary>Forgets the entity the mapper last built from this model.</summary>
    internal void ForgetApplied()
    {
        _appliedEntity = null;
        _readBackApplied = null;
    }

    /// <summary>Accepts the outcome of saving <paramref name="entity"/>, the entity built from this model, for this model and its cascade children.</summary>
    /// <remarks>
    /// The entity's state after the save tells what happened to it: Unchanged means the row was written, so its values (a new
    /// version, values the database or a save hook set) are read back and the model becomes Unchanged. Added or Updated
    /// means a save hook skipped it, so the model keeps its state and the next save tries it again. Removed means the row was
    /// deleted, so the model stays Removed and nothing below it is touched (the deletion took the subtree with it); a deletion
    /// a hook skipped cannot be told apart from it at this level.
    /// </remarks>
    /// <param name="entity">The entity that was saved.</param>
    /// <param name="readBack">Reads the entity back into this model (null reads nothing).</param>
    internal void AcceptSaved(EntityBaseCore entity, Action? readBack)
    {
        ForgetApplied();

        if (entity.IsRemoved)
        {
            return;
        }

        if (!entity.HasChanges)
        {
            readBack?.Invoke();
            MarkUnchanged();
        }

        foreach (var link in ChildLinks)
        {
            link.AcceptSaved(entity);
        }
    }

    /// <summary>Accepts the save of the entity recorded for this model, when one is recorded (a model added after the entities were built is left as it is).</summary>
    internal void AcceptSavedApplied()
    {
        if (_appliedEntity is { } entity)
        {
            AcceptSaved(entity, _readBackApplied);
        }
    }

    /// <summary>Gets a value indicating whether this model is marked for insertion.</summary>
    public bool IsAdded => RowState == RowState.Added;

    /// <summary>Gets a value indicating whether this model is marked for update.</summary>
    public bool IsUpdated => RowState == RowState.Updated;

    /// <summary>Gets a value indicating whether this model is marked for deletion.</summary>
    public bool IsRemoved => RowState == RowState.Removed;

    /// <summary>Gets a value indicating whether there are any changes (insert, update, or delete).</summary>
    public bool HasChanges => RowState != RowState.Unchanged;

    /// <summary>Marks this model for insertion (used to include a newly entered edit model in a save).</summary>
    public void MarkAdded() => RowState = RowState.Added;

    /// <summary>Marks this model and its whole cascade subtree for insertion (used when the stored rows behind the subtree are gone).</summary>
    /// <remarks>
    /// <see cref="EditModelCollection{T}.AcceptRemoved"/> uses this for the set-aside elements: the saved deletion removed
    /// their descendants with them (a graph delete cascades), so adding the instance back means inserting the graph it
    /// still holds. Marking only the root would insert the parent and silently drop the children - a graph save does not
    /// write Unchanged rows. Child collections release their own deletion tracking the same way, so what the subtree
    /// still holds is exactly what a re-add will insert.
    /// </remarks>
    internal void MarkSubtreeAdded()
    {
        MarkAdded();

        foreach (var link in ChildLinks)
        {
            link.MarkSubtreeAdded();
        }
    }

    /// <summary>Marks this model for deletion (it stays in the collection and is deleted on save).</summary>
    /// <remarks>
    /// <para>
    /// From here on the model is out of scope for <see cref="Validate"/> and <see cref="CollectErrors(bool)"/>: only its key
    /// takes part in the save. Its own errors stay registered, so a per-row display keeps showing them and putting the row back
    /// brings them back into the validation.
    /// </para>
    /// <para>
    /// After the save, <see cref="EditModelCollection{T}.AcceptChanges"/> takes a marked element out of its collection (it no
    /// longer describes a stored row). A single cascade child has no collection to leave: it stays attached and stays Removed,
    /// so set the parent's navigation property to null once the save is confirmed.
    /// </para>
    /// </remarks>
    public void MarkRemoved() => RowState = RowState.Removed;

    /// <summary>Sets the state to unchanged (saved).</summary>
    public void MarkUnchanged() => RowState = RowState.Unchanged;

    /// <summary>Marks this model for update only when it is currently unchanged (called when a confirmed value changes).</summary>
    public void MarkUpdated()
    {
        if (RowState == RowState.Unchanged)
        {
            RowState = RowState.Updated;
        }
    }

    /// <summary>Cross-cutting hook invoked after a confirmed-value property changes (only on user edits; not called during load). Use it for stamping UpdatedAt and similar.</summary>
    /// <remarks>When updating another confirmed-value property inside this hook, check <paramref name="propertyName"/> to avoid infinite recursion.</remarks>
    protected virtual void OnConfirmedValueChanged(string propertyName) { }

    /// <summary>Gets a value indicating whether a confirmed-value change should promote <see cref="RowState"/> to Updated (default true; override to exclude specific properties such as metadata).</summary>
    protected virtual bool ShouldMarkUpdated(string propertyName) => true;

    /// <summary>Normalizes a UI input string (trims leading and trailing whitespace, tabs, and newlines, including full-width spaces).</summary>
    protected string NormalizeInput(string propertyName, string value)
    {
        // Bindings such as ComboBox may write null at runtime, so allow it (null is handled as empty input by the conversion branch).
        if (value is null)
        {
            return value!;
        }

        // Trim only leading and trailing whitespace (preserve interior whitespace and newlines).
        var normalized = value.Trim();
        CustomizeInputNormalization(propertyName, value, ref normalized);
        return normalized;
    }

    /// <summary>Adjusts input normalization per column (for example, restore <paramref name="rawValue"/> into <paramref name="normalizedValue"/> for a column where trimming should be disabled; override to add processing).</summary>
    protected virtual void CustomizeInputNormalization(
        string propertyName,
        string rawValue,
        ref string normalizedValue
    ) { }

    /// <summary>Runs the shared tail of a confirmed-value setter: raises the change notification, and outside a load retires the stale database verdicts and promotes the row to an update target.</summary>
    /// <remarks>
    /// The generated setter keeps only what is its own - the equality cut, the four <c>On{Property}Changing/Changed</c>
    /// hook calls, and the field write - and ends here. The order (notify, then the not-loading block) is the order the
    /// setters always had.
    /// </remarks>
    /// <param name="propertyName">The confirmed-value property that changed.</param>
    protected void AfterConfirmedValueSet(string propertyName)
    {
        OnPropertyChanged(propertyName);

        // Promote to update target when the confirmed value changes (not during load, where the state stays a mirror of the source entity).
        if (!IsLoading)
        {
            // The database check compared the values this model held a moment ago, so editing one makes its verdict stale.
            ClearDuplicateErrors(DuplicateErrorSource.Database);
            OnConfirmedValueChanged(propertyName);

            if (ShouldMarkUpdated(propertyName))
            {
                MarkUpdated();
            }
        }
    }

    /// <summary>Accepts a write to a binding string: normalizes input (outside load/revert), stores it, and resets the display when trimming collapsed the change into equality. Returns true when the write is a real change outside a revert, i.e. when the confirmed value should be re-derived from <paramref name="normalized"/>.</summary>
    /// <param name="field">The backing field of the binding property.</param>
    /// <param name="value">The raw value written by the binding.</param>
    /// <param name="bindingPropertyName">The binding property's name (for notification and normalization hooks).</param>
    /// <param name="normalized">The stored, normalized input string.</param>
    protected bool AcceptBindingInput(
        ref string field,
        string value,
        string bindingPropertyName,
        out string normalized
    )
    {
        // Normalize only values that come from input (pass through during load/revert to keep a mirror of the source entity).
        normalized = IsLoading || IsReverting ? value : NormalizeInput(bindingPropertyName, value);

        if (!SetProperty(ref field, normalized, bindingPropertyName))
        {
            // When trimming makes the value equal to the existing one, only the on-screen display keeps the whitespace-padded string, so reset the display to the normalized value.
            if (!string.Equals(value, normalized, StringComparison.Ordinal))
            {
                OnPropertyChanged(bindingPropertyName);
            }

            return false;
        }

        return !IsReverting;
    }

    /// <summary>Outcome of converting a normalized input string toward a confirmed value.</summary>
    /// <remarks>
    /// The conversion helpers return state instead of acting so that the generated setter keeps ownership of what
    /// happens next - the typed assignment, the error write, and the parse-failure message, whose resolution runs
    /// through per-type partial hooks a base class cannot call.
    /// </remarks>
    protected enum BindingConversion
    {
        /// <summary>The input converted; assign the value and clear the input error.</summary>
        Converted,

        /// <summary>A value object rejected the value; the rejection text carries its validation errors.</summary>
        Rejected,

        /// <summary>The input could not be parsed as the underlying type; the caller resolves the message.</summary>
        Unparsable,
    }

    /// <summary>Parses a normalized input string as <typeparamref name="TValue"/> (the same semantics as the type's own TryParse with the current culture).</summary>
    /// <param name="normalized">The normalized input string.</param>
    /// <param name="parsed">The parsed value.</param>
    protected static bool TryParseInput<TValue>(string normalized, out TValue parsed)
        where TValue : IParsable<TValue> => TValue.TryParse(normalized, null, out parsed!);

    /// <summary>Converts a normalized input string to binary (empty becomes an empty array; Base64 otherwise).</summary>
    /// <param name="normalized">The normalized input string.</param>
    /// <param name="bytes">The converted bytes (empty when the conversion failed).</param>
    protected static bool TryConvertBase64Input(string normalized, out byte[] bytes)
    {
        if (string.IsNullOrEmpty(normalized))
        {
            bytes = Array.Empty<byte>();
            return true;
        }

        try
        {
            bytes = Convert.FromBase64String(normalized);
            return true;
        }
        catch (FormatException)
        {
            bytes = Array.Empty<byte>();
            return false;
        }
    }

    /// <summary>Converts a normalized input string to a parsable value (empty converts to null so a blank input clears the confirmed value; the required check decides whether null is acceptable).</summary>
    /// <param name="normalized">The normalized input string.</param>
    /// <param name="converted">The parsed value, or null for empty input or on failure.</param>
    protected static BindingConversion ConvertParsedInput<TValue>(string normalized, out TValue? converted)
        where TValue : struct, IParsable<TValue>
    {
        if (string.IsNullOrEmpty(normalized))
        {
            converted = null;
            return BindingConversion.Converted;
        }

        if (TryParseInput<TValue>(normalized, out var parsed))
        {
            converted = parsed;
            return BindingConversion.Converted;
        }

        converted = null;
        return BindingConversion.Unparsable;
    }

    /// <summary>Converts a normalized input string to binary (empty converts to null so a blank input clears the confirmed value; the required check decides whether null is acceptable).</summary>
    /// <param name="normalized">The normalized input string.</param>
    /// <param name="converted">The converted bytes, or null for empty input or on failure.</param>
    protected static BindingConversion ConvertBinaryInput(string normalized, out byte[]? converted)
    {
        if (string.IsNullOrEmpty(normalized))
        {
            converted = null;
            return BindingConversion.Converted;
        }

        if (TryConvertBase64Input(normalized, out var bytes))
        {
            converted = bytes;
            return BindingConversion.Converted;
        }

        converted = null;
        return BindingConversion.Unparsable;
    }

    /// <summary>Gets or sets the collection this edit model belongs to (for sibling navigation; set by <see cref="EditModelCollection{T}"/>).</summary>
    internal IList? Owner { get; set; }

    /// <summary>Returns the next element after this one in its owning collection (null if not owned or at the end).</summary>
    public EditModelBaseCore? GetNext()
    {
        if (Owner is null)
        {
            return null;
        }

        var index = Owner.IndexOf(this);
        return index >= 0 && index + 1 < Owner.Count ? (EditModelBaseCore?)Owner[index + 1] : null;
    }

    /// <summary>Returns the previous element before this one in its owning collection (null if not owned or at the start).</summary>
    public EditModelBaseCore? GetPrevious()
    {
        if (Owner is null)
        {
            return null;
        }

        var index = Owner.IndexOf(this);
        return index > 0 ? (EditModelBaseCore?)Owner[index - 1] : null;
    }

    /// <summary>Gets the position of this element within its owning collection (-1 if not owned).</summary>
    public int IndexInParent => Owner?.IndexOf(this) ?? -1;

    /// <summary>Gets a value indicating whether this is the first element in its owning collection (false if not owned).</summary>
    public bool IsFirstInParent => IndexInParent == 0;

    /// <summary>Gets a value indicating whether this is the last element in its owning collection (false if not owned).</summary>
    public bool IsLastInParent
    {
        get
        {
            var index = IndexInParent;
            return index >= 0 && Owner is not null && index == Owner.Count - 1;
        }
    }

    /// <summary>Removes this element from its owning collection (existing elements are tracked as Removed). Returns true if removed.</summary>
    public bool RemoveFromParent()
    {
        if (Owner is null || !Owner.Contains(this))
        {
            return false;
        }

        Owner.Remove(this);
        return true;
    }

    /// <summary>Moves this element to the start of its owning collection (reorders only, no deletion tracking). Returns true if moved.</summary>
    public bool MoveToFirst() => MoveSelfTo(0);

    /// <summary>Moves this element to the end of its owning collection. Returns true if moved.</summary>
    public bool MoveToLast() => Owner is not null && MoveSelfTo(Owner.Count - 1);

    /// <summary>Moves this element one position later in its owning collection. Returns true if moved.</summary>
    public bool MoveToNext()
    {
        var index = IndexInParent;
        return index >= 0 && Owner is not null && index + 1 < Owner.Count && MoveSelfTo(index + 1);
    }

    /// <summary>Moves this element one position earlier in its owning collection. Returns true if moved.</summary>
    public bool MoveToPrevious()
    {
        var index = IndexInParent;
        return index > 0 && MoveSelfTo(index - 1);
    }

    /// <summary>Shared logic to move this element to the specified position in its owning collection (via ObservableCollection.Move so no deletion tracking occurs).</summary>
    private bool MoveSelfTo(int newIndex)
    {
        if (Owner is null)
        {
            return false;
        }

        var oldIndex = Owner.IndexOf(this);
        if (oldIndex < 0 || oldIndex == newIndex)
        {
            return false;
        }

        MoveCore(oldIndex, newIndex);
        return true;
    }

    /// <summary>Core reorder logic for the owning collection (concrete classes implement Move on the typed collection).</summary>
    protected virtual void MoveCore(int oldIndex, int newIndex) { }

    /// <summary>Raises change notifications for the position properties (<see cref="IndexInParent"/> / <see cref="IsFirstInParent"/> / <see cref="IsLastInParent"/>), called when the collection changes or is reordered.</summary>
    internal void RaisePositionChanged()
    {
        OnPropertyChanged(nameof(IndexInParent));
        OnPropertyChanged(nameof(IsFirstInParent));
        OnPropertyChanged(nameof(IsLastInParent));
    }

    /// <summary>Raises the change notification for the owning collection reference (ParentCollection), called when the element enters or leaves a collection (the property lives on <see cref="EditModelBaseCore{TSelf}"/> under exactly this name).</summary>
    internal void RaiseParentCollectionChanged() => OnPropertyChanged("ParentCollection");

    /// <summary>The parent model that holds this element as a child (cascade parent). Set by the owning collection or single reference; null when not owned or at the root.</summary>
    private EditModelBaseCore? _parentModel;

    /// <summary>Gets the parent edit model that holds this element as a child (set via either a collection or a single reference; null when not owned or at the root).</summary>
    /// <remarks>In concrete classes where the parent type is unambiguous, a typed ParentModel with the same name is generated and hides this property.</remarks>
    public EditModelBaseCore? ParentModel => _parentModel;

    /// <summary>Sets the parent model reference and raises the <see cref="ParentModel"/> change notification only when it changes (called by the owning setter or collection).</summary>
    internal void SetParentModel(EditModelBaseCore? parentModel)
    {
        if (ReferenceEquals(_parentModel, parentModel))
        {
            return;
        }

        _parentModel = parentModel;
        OnPropertyChanged(nameof(ParentModel));
    }

    /// <summary>Raises a change notification for the specified property.</summary>
    protected void OnPropertyChanged(string propertyName) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));

    /// <summary>Shared helper that assigns and raises a change notification only when the value changes (concrete classes can override to extend the behavior).</summary>
    protected virtual bool SetProperty<T>(ref T field, T value, string propertyName)
    {
        if (EqualityComparer<T>.Default.Equals(field, value))
        {
            return false;
        }

        field = value;
        OnPropertyChanged(propertyName);
        return true;
    }

    /// <summary>Returns a child collection, adopting it as this model's child the first time it is read (the getter of a generated child collection property).</summary>
    /// <param name="field">The backing field of the child collection property.</param>
    protected EditModelCollection<T> GetChildren<T>(EditModelCollection<T> field)
        where T : EditModelBaseCore
    {
        field.OwnerModel ??= this;
        return field;
    }

    /// <summary>Replaces a child collection: the outgoing one is released, the incoming one is adopted, and the change notification is raised (the setter of a generated child collection property).</summary>
    /// <param name="field">The backing field of the child collection property.</param>
    /// <param name="value">The collection to put in its place.</param>
    /// <param name="propertyName">The child collection property's name (for the change notification).</param>
    protected void SetChildren<T>(
        ref EditModelCollection<T> field,
        EditModelCollection<T> value,
        string propertyName
    )
        where T : EditModelBaseCore
    {
        if (ReferenceEquals(field, value))
        {
            return;
        }

        field.OwnerModel = null;
        field = value;
        field.OwnerModel = this;
        OnPropertyChanged(propertyName);
    }

    /// <summary>Returns the errors for the specified property (all errors when null). Input errors come first, then duplicate-value errors.</summary>
    /// <remarks>
    /// The result is a finished list, never a deferred view over the error stores. A binding layer holds on to what this
    /// returns and enumerates it later, by which time a validation pass may well have registered or withdrawn an error; a
    /// deferred query would then read the stores mid-change - and, for the all-properties form, enumerate the very
    /// dictionaries a <c>Clear</c> is emptying.
    /// </remarks>
    public IEnumerable GetErrors(string? propertyName)
    {
        if (string.IsNullOrEmpty(propertyName))
        {
            return _errors
                .Values.Select(error => error.Message)
                .Concat(_duplicateErrors.Values.SelectMany(entry => entry.Messages()))
                .ToList();
        }

        return ReadErrors(propertyName);
    }

    /// <summary>Reads the messages registered for the specified property in both stores (the input error first, then the duplicate-value errors).</summary>
    private List<string> ReadErrors(string propertyName)
    {
        var messages = new List<string>();

        if (_errors.TryGetValue(propertyName, out var input))
        {
            messages.Add(input.Message);
        }

        if (_duplicateErrors.TryGetValue(propertyName, out var duplicates))
        {
            messages.AddRange(duplicates.Messages());
        }

        return messages;
    }

    /// <summary>Combines a child element path (empty at the root, "."-separated below).</summary>
    protected static string CombineErrorPath(string path, string segment) =>
        path.Length == 0 ? segment : path + "." + segment;

    /// <summary>Checks required fields for missing input, runs additional validation, and registers errors (returns true when there are no errors).</summary>
    /// <param name="includeChildren">True to cascade validation to children as well, false to validate only this model.</param>
    /// <remarks>
    /// A model marked for deletion (<see cref="IsRemoved"/>) is out of scope, children included: only its key takes part in the
    /// save, so the input on a row that is about to be deleted has nothing to say about whether the save can go ahead. The error
    /// stores are left untouched, so putting a removed row back (which restores the state it had before the removal) brings its
    /// errors back with it.
    /// </remarks>
    public bool Validate(bool includeChildren = true)
    {
        if (IsRemoved)
        {
            return true;
        }

        ValidateSelf();

        var valid = !HasErrors;

        if (includeChildren)
        {
            foreach (var link in ChildLinks)
            {
                // Do not short-circuit, so that errors are registered on every child.
                if (!link.Validate(includeChildren))
                {
                    valid = false;
                }
            }
        }

        return valid;
    }

    /// <summary>Validates this node itself (concrete classes implement required-field checks and similar).</summary>
    protected virtual void ValidateSelf() { }

    /// <summary>Collects validation errors with each node's path (call Validate beforehand).</summary>
    /// <param name="includeChildren">True to recursively collect from cascade children as well, false for this model's errors only.</param>
    /// <remarks>
    /// A model marked for deletion (<see cref="IsRemoved"/>) is skipped along with its subtree, matching what
    /// <see cref="Validate"/> leaves out: a row that is about to be deleted contributes nothing that could block the save.
    /// Its own <see cref="HasErrors"/> and <see cref="GetErrors"/> are untouched, so a per-row display still shows the errors.
    /// </remarks>
    public IEnumerable<EditModelError> CollectErrors(bool includeChildren = true)
    {
        var errors = new List<EditModelError>();
        CollectErrors(string.Empty, includeChildren, errors);
        return errors;
    }

    /// <summary>Internal implementation that collects validation errors with paths into <paramref name="errors"/> (used by recursive child calls).</summary>
    internal void CollectErrors(string path, bool includeChildren, List<EditModelError> errors)
    {
        if (IsRemoved)
        {
            return;
        }

        errors.AddRange(CollectOwnErrors(path));

        if (!includeChildren)
        {
            return;
        }

        foreach (var link in ChildLinks)
        {
            link.CollectErrors(path, includeChildren, errors);
        }
    }

    /// <summary>Enumerates this edit model's own errors with the specified path (building block for graph collection). Input errors come first, then duplicate-value errors.</summary>
    /// <remarks>The result is a finished list rather than a deferred query, for the same reason as <see cref="GetErrors"/>: nothing that escapes this class enumerates the error stores later on.</remarks>
    protected IEnumerable<EditModelError> CollectOwnErrors(string path)
    {
        var errors = new List<EditModelError>();

        foreach (var pair in _errors)
        {
            errors.Add(new EditModelError(path, pair.Key, pair.Value.Message));
        }

        foreach (var pair in _duplicateErrors)
        {
            foreach (var message in pair.Value.Messages())
            {
                errors.Add(new EditModelError(path, pair.Key, message));
            }
        }

        return errors;
    }

    /// <summary>Resets the graph to the unchanged state after a save is confirmed (marks this model Unchanged, takes saved deletions out of child collections, and clears their deletion tracking).</summary>
    /// <remarks>
    /// This accepts every change without looking at the save. After saving the entities a mapper built from this model, use
    /// the mapper's <c>AcceptSaved(editModel, entity)</c> instead: it reads back what the
    /// save wrote (a new version among them, without which the next save fails as a conflict) and keeps what a save hook skipped.
    /// </remarks>
    /// <param name="includeChildren">True to recursively accept changes on cascade children as well.</param>
    public void AcceptChanges(bool includeChildren = true)
    {
        MarkUnchanged();

        if (includeChildren)
        {
            foreach (var link in ChildLinks)
            {
                link.AcceptChanges(includeChildren);
            }
        }
    }

    /// <summary>Returns whether this model or its cascade children have changes (used for enabling a save button and similar).</summary>
    /// <param name="includeChildren">True to include changes on cascade children in the check.</param>
    public bool HasGraphChanges(bool includeChildren = true)
    {
        if (HasChanges)
        {
            return true;
        }

        if (!includeChildren)
        {
            return false;
        }

        foreach (var link in ChildLinks)
        {
            if (link.HasChanges(includeChildren))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>Links to cascade children (known navigations plus partial additions). Backing field.</summary>
    private List<ChildLink>? _childLinks;

    /// <summary>Whether child registration has been executed once.</summary>
    private bool _childrenRegistered;

    /// <summary>List of cascade child links. Calls RegisterChildren / RegisterExtraChildren exactly once on first access.</summary>
    private IReadOnlyList<ChildLink> ChildLinks
    {
        get
        {
            if (!_childrenRegistered)
            {
                _childrenRegistered = true;
                RegisterChildren();
                RegisterExtraChildren();
            }

            if (_childLinks is null)
            {
                return Array.Empty<ChildLink>();
            }

            return _childLinks;
        }
    }

    /// <summary>Registers the known cascade children (only generated code of concrete classes with cascade children overrides this; do not implement manually).</summary>
    protected virtual void RegisterChildren() { }

    /// <summary>Extension point to register children added in a partial class via AddChild / AddChildren. Overriding makes them participate in validation, error collection, accepting changes, and dirty checks.</summary>
    protected virtual void RegisterExtraChildren() { }

    /// <summary>Registers a single child reference into the cascade (the reference is resolved lazily so the latest value is used).</summary>
    protected void AddChild(string name, Func<EditModelBaseCore?> accessor) =>
        (_childLinks ??= new()).Add(ChildLink.ForSingle(name, accessor));

    /// <summary>Registers a child collection into the cascade (the collection is resolved lazily so the latest instance is used, even after a mapper load replaces it). While the accessor returns null the link counts as empty, the same way a single child does.</summary>
    protected void AddChildren<T>(string name, Func<EditModelCollection<T>?> accessor)
        where T : EditModelBaseCore =>
        (_childLinks ??= new()).Add(ChildLink.ForCollection(name, accessor));

    /// <summary>Link to a registered child (cascade participant). Treats single references and child collections uniformly.</summary>
    /// <remarks>
    /// Every operation goes through the accessor the link was created with, so a child reference or child collection that is
    /// replaced later (a mapper load rebuilds the collection, for instance) is still the one that validation, error collection,
    /// accepting changes, and dirty checks see.
    /// </remarks>
    private sealed class ChildLink
    {
        private readonly string _name;
        private readonly bool _isCollection;
        private readonly Func<IEnumerable<EditModelBaseCore>> _items;
        private readonly Func<bool, bool> _validate;
        private readonly Func<bool, bool> _hasChanges;
        private readonly Action<bool> _acceptChanges;
        private readonly Action _markSubtreeAdded;
        private readonly Action<EntityBaseCore> _acceptSaved;

        private ChildLink(
            string name,
            bool isCollection,
            Func<IEnumerable<EditModelBaseCore>> items,
            Func<bool, bool> validate,
            Func<bool, bool> hasChanges,
            Action<bool> acceptChanges,
            Action markSubtreeAdded,
            Action<EntityBaseCore> acceptSaved
        )
        {
            _name = name;
            _isCollection = isCollection;
            _items = items;
            _validate = validate;
            _hasChanges = hasChanges;
            _acceptChanges = acceptChanges;
            _markSubtreeAdded = markSubtreeAdded;
            _acceptSaved = acceptSaved;
        }

        /// <summary>Creates a link that registers a single child reference.</summary>
        /// <remarks>
        /// Accepting changes skips a child marked Removed: its row has just been deleted, so accepting it would turn it
        /// into an Unchanged ghost of a row that no longer exists. It has no collection to leave, so it stays attached
        /// and stays Removed - the application sets the navigation property to null once the save is confirmed
        /// (see <see cref="MarkRemoved"/>).
        /// </remarks>
        public static ChildLink ForSingle(string name, Func<EditModelBaseCore?> accessor) =>
            new(
                name,
                false,
                () => accessor() is { } child ? new[] { child } : Enumerable.Empty<EditModelBaseCore>(),
                includeChildren => accessor() is not { } child || child.Validate(includeChildren),
                includeChildren =>
                    accessor() is { } child && child.HasGraphChanges(includeChildren),
                includeChildren =>
                {
                    if (accessor() is { IsRemoved: false } child)
                    {
                        child.AcceptChanges(includeChildren);
                    }
                },
                () => accessor()?.MarkSubtreeAdded(),
                _ =>
                {
                    // A new row marked for deletion was left out of the save, so there is nothing to accept for it
                    if (accessor() is { IsDiscardedNewRow: false } child)
                    {
                        child.AcceptSavedApplied();
                    }
                }
            );

        /// <summary>Creates a link that registers a child collection.</summary>
        /// <remarks>
        /// Validation is delegated to <see cref="EditModelCollection{T}.Validate"/> rather than looping over the elements here,
        /// so validating the parent also runs the duplicate check among the siblings. Accepting changes is delegated the same
        /// way, so the collection's own handling of saved deletions (removing the marked elements) runs on the parent's
        /// AcceptChanges too.
        /// </remarks>
        public static ChildLink ForCollection<T>(string name, Func<EditModelCollection<T>?> accessor)
            where T : EditModelBaseCore =>
            new(
                name,
                true,
                () => (IEnumerable<EditModelBaseCore>?)accessor() ?? Enumerable.Empty<EditModelBaseCore>(),
                includeChildren => accessor() is not { } children || children.Validate(includeChildren),
                _ => accessor() is { HasChanges: true },
                includeChildren => accessor()?.AcceptChanges(includeChildren),
                () => accessor()?.MarkSubtreeAdded(),
                parentEntity => accessor()?.AcceptSaved(parentEntity)
            );

        /// <summary>Validates the registered children and returns true when they are all valid.</summary>
        public bool Validate(bool includeChildren) => _validate(includeChildren);

        /// <summary>Collects the registered children's errors with paths (name[i] for collections, name for single references).</summary>
        public void CollectErrors(
            string parentPath,
            bool includeChildren,
            List<EditModelError> errors
        )
        {
            var index = 0;

            foreach (var item in _items())
            {
                var segment = _isCollection ? $"{_name}[{index}]" : _name;
                item.CollectErrors(CombineErrorPath(parentPath, segment), includeChildren, errors);
                index++;
            }
        }

        /// <summary>Accepts changes on the registered children (collections delegate to their own AcceptChanges, which also handles saved deletions and clears deletion tracking).</summary>
        public void AcceptChanges(bool includeChildren) => _acceptChanges(includeChildren);

        /// <summary>Marks the registered children's subtrees for insertion (building block of <see cref="EditModelBaseCore.MarkSubtreeAdded"/>).</summary>
        public void MarkSubtreeAdded() => _markSubtreeAdded();

        /// <summary>Accepts the save of the registered children, given the saved entity of their parent.</summary>
        public void AcceptSaved(EntityBaseCore parentEntity) => _acceptSaved(parentEntity);

        /// <summary>Returns whether the registered children have changes.</summary>
        public bool HasChanges(bool includeChildren) => _hasChanges(includeChildren);
    }

    /// <summary>Sets the input error for the specified property (pass null to clear). Duplicate-value errors live in their own store and are not affected.</summary>
    /// <remarks>A property carries one input error at a time, so this also replaces a missing-required-input error left by a previous validation.</remarks>
    protected void SetError(string propertyName, string? error)
    {
        if (error is null)
        {
            ClearErrors(propertyName);
            return;
        }

        _errors[propertyName] = new InputError(error, FromRequiredCheck: false);
        OnErrorsChanged(propertyName);
    }

    /// <summary>Clears the input error for the specified property, whichever check registered it. Duplicate-value errors live in their own store and are cleared by ClearDuplicateErrors.</summary>
    protected void ClearErrors(string propertyName)
    {
        if (_errors.Remove(propertyName))
        {
            OnErrorsChanged(propertyName);
        }
    }

    /// <summary>Registers a missing-required-input error on the specified property, unless it already carries another input error (called by the generated required-field check).</summary>
    /// <remarks>
    /// <para>
    /// A conversion error means the field does hold input that simply cannot be converted, which is the more upstream cause and the
    /// message the user has to act on. Replacing it with "is required" would hide the real problem behind a wrong one, and the
    /// conversion error can only ever be produced again by the binding setter.
    /// </para>
    /// <para>
    /// Registering the very same message this check already registered changes nothing about the property, so
    /// <see cref="ErrorsChanged"/> is not raised for it: validation is run repeatedly over a model that is still incomplete,
    /// and announcing a change that did not happen makes every one of those runs redraw the bound field.
    /// </para>
    /// </remarks>
    protected void SetRequiredError(string propertyName, string message)
    {
        if (_errors.TryGetValue(propertyName, out var existing))
        {
            if (!existing.FromRequiredCheck)
            {
                return;
            }

            if (string.Equals(existing.Message, message, StringComparison.Ordinal))
            {
                return;
            }
        }

        _errors[propertyName] = new InputError(message, FromRequiredCheck: true);
        OnErrorsChanged(propertyName);
    }

    /// <summary>Clears the missing-required-input error registered on the specified property (called by the generated required-field check once the value is present).</summary>
    /// <remarks>
    /// Only an error the required check itself registered is removed: a conversion error belongs to the binding setter and an error
    /// registered from OnValidate belongs to that hook, so neither is cleared here.
    /// </remarks>
    protected void ClearRequiredError(string propertyName)
    {
        if (!_errors.TryGetValue(propertyName, out var existing) || !existing.FromRequiredCheck)
        {
            return;
        }

        _errors.Remove(propertyName);
        OnErrorsChanged(propertyName);
    }

    /// <summary>Raises the input-errors change notification, and a PropertyChanged for <see cref="HasErrors"/> (it is derived from the same stores, so a binding to it - a save button's IsEnabled, say - updates together with the errors).</summary>
    protected void OnErrorsChanged(string propertyName)
    {
        ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
        OnPropertyChanged(nameof(HasErrors));
    }

    /// <summary>Clears every duplicate-value error, whichever check found it (input errors, which live in a separate store, are left untouched). Loading a new value into the model uses this.</summary>
    public void ClearDuplicateErrors() => ClearDuplicateErrorsCore(null);

    /// <summary>Clears the duplicate-value errors found by the specified check only, leaving the other check's findings in place.</summary>
    /// <remarks>
    /// <para>
    /// Each check clears exactly what it registered before running again, so the check among the siblings no longer discards
    /// the violations the database check found (and the other way round). Changing a confirmed value also clears the
    /// <see cref="DuplicateErrorSource.Database"/> findings of the whole model, because they were reached by comparing the values
    /// it held before the edit - all of them, since a composite constraint's verdict rests on every column it covers.
    /// </para>
    /// <para>
    /// That sweep is per model, not per property, so editing one column also withdraws a database finding standing on another
    /// column of the same model, and <see cref="HasErrors"/> can read false until the check is run again. The window is
    /// deliberate: the alternative is reporting a violation that was established against values the model no longer holds. The
    /// definitive guarantee is the database's own UNIQUE constraint either way, so run the check again before saving.
    /// </para>
    /// </remarks>
    /// <param name="source">The check whose findings are cleared. An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    public void ClearDuplicateErrors(DuplicateErrorSource source) =>
        ClearDuplicateErrorsCore(source);

    /// <summary>Shared implementation of the two ClearDuplicateErrors overloads (null clears every source).</summary>
    private void ClearDuplicateErrorsCore(DuplicateErrorSource? source)
    {
        // Before the early return: a check in flight has to learn that its values changed even when nothing was registered yet
        if (source is null or DuplicateErrorSource.Database)
        {
            _databaseCheckGeneration++;
        }

        if (_duplicateErrors.Count == 0)
        {
            return;
        }

        // The properties to touch are listed first, because the store is modified while they are processed
        var cleared = _duplicateErrors
            .Where(pair => source is null || pair.Value.Of(source.Value) is not null)
            .Select(pair => pair.Key)
            .ToList();

        foreach (var propertyName in cleared)
        {
            if (source is null)
            {
                _duplicateErrors.Remove(propertyName);
            }
            else
            {
                // Only the calling check's slot is emptied; the entry stays as long as the other check still has a finding
                var remaining = _duplicateErrors[propertyName].With(source.Value, null);

                if (remaining.IsEmpty)
                {
                    _duplicateErrors.Remove(propertyName);
                }
                else
                {
                    _duplicateErrors[propertyName] = remaining;
                }
            }

            OnErrorsChanged(propertyName);
        }
    }

    /// <summary>Registers a duplicate-value error on the specified binding property in the duplicate-value store. An empty name registers a model-level error.</summary>
    /// <remarks>
    /// It does not go through <see cref="SetError"/>, so a conversion error already registered on the same property survives and both are
    /// reported. Only the calling check's slot is written, so a property found to be a duplicate both among its siblings and against the
    /// database reports both findings, and each of them disappears when its own check stops finding it.
    /// <para>
    /// The two slots are withdrawn on different occasions. A <see cref="DuplicateErrorSource.Database"/> finding is dropped as soon as a
    /// confirmed value of this model changes, since it was reached by comparing the values held before the edit. A
    /// <see cref="DuplicateErrorSource.Siblings"/> finding stays until the check over the collection runs again: it is a statement about
    /// two models holding the same value, and the matching finding on the other model can only be withdrawn by that check, so retracting
    /// one side on its own edit would leave the other side flagged alone.
    /// </para>
    /// </remarks>
    /// <param name="propertyName">Binding property the error is attached to (empty for a model-level error).</param>
    /// <param name="message">The error message.</param>
    /// <param name="source">The check that found the duplicate (it decides which slot is written and which clear removes the error again). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    public void SetDuplicateError(
        string propertyName,
        string message,
        DuplicateErrorSource source = DuplicateErrorSource.Siblings
    )
    {
        _duplicateErrors[propertyName] = _duplicateErrors
            .GetValueOrDefault(propertyName)
            .With(source, message);
        OnErrorsChanged(propertyName);
    }

    /// <summary>
    /// Registers a duplicate-value error for the given confirmed-value property names. <see cref="EditModelBaseCore{TSelf}"/> maps the
    /// names to their binding properties through the column table and resolves the display names; names that cannot be mapped
    /// (and an empty list) produce a model-level error, which is all this fallback does.
    /// </summary>
    /// <param name="propertyNames">Confirmed-value property names that make up the violated constraint.</param>
    /// <param name="message">Message that replaces the default one (null to build the default from <see cref="EditModelMessages.DuplicateValue"/>).</param>
    /// <param name="source">The check that found the duplicate (it decides which clear removes the error again). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    public virtual void RegisterDuplicateError(
        IReadOnlyList<string> propertyNames,
        string? message,
        DuplicateErrorSource source = DuplicateErrorSource.Siblings
    ) =>
        SetDuplicateError(
            string.Empty,
            message ?? EditModelMessages.DuplicateValue(propertyNames, propertyNames),
            source
        );

    /// <summary>
    /// Gets the UNIQUE constraints of the underlying table (none by default). Generated edit models whose table declares
    /// UNIQUE constraints override this with the constraints and their compiled value accessors.
    /// </summary>
    /// <remarks>
    /// It is the input of the duplicate check among the elements of a collection (<see cref="EditModelUniquenessValidator"/>),
    /// so the check needs no reflection. Application code can add its own constraints by overriding this in a partial class.
    /// </remarks>
    public virtual IReadOnlyList<EditModelUniquenessConstraint> UniquenessConstraints =>
        Array.Empty<EditModelUniquenessConstraint>();

    /// <summary>Asks the repository which UNIQUE constraints the given entity violates and registers the findings as duplicate-value errors (returns true when there are none).</summary>
    /// <remarks>
    /// <para>
    /// The body of the generated <c>ValidateUniqueAsync</c>: everything except building the entity from the confirmed values,
    /// which is the only part that needs the concrete types. The findings of the previous run are withdrawn before the query
    /// goes out, so re-checking never leaves stale errors, and only this check's slot is touched - what the check among the
    /// siblings reported stays.
    /// </para>
    /// <para>
    /// The findings are registered only if they are still about the values the model holds. When a confirmed value is edited,
    /// the model is reloaded or its edit cancelled, or another check starts while the query is out, what the query found is
    /// about values the model no longer holds: nothing is registered and the result is <c>false</c>, meaning that the current
    /// values were not confirmed unique. Run the check again.
    /// </para>
    /// <para>
    /// A model marked for removal passes without a query, the same as every other read of the validation state
    /// (<see cref="Validate"/>, the error collection, and the check among the siblings all skip it): only its key reaches the
    /// save, so a duplicate in a value that is about to be deleted must not block one. The error store is left untouched, so a
    /// row whose removal is undone is judged again by the next check.
    /// </para>
    /// </remarks>
    /// <param name="repository">The repository used for the check.</param>
    /// <param name="entity">The entity carrying the values to check.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    protected Task<bool> CheckDatabaseUniquenessAsync<TEntity, TKey>(
        IRemoteRepositoryCore<TEntity, TKey> repository,
        TEntity entity,
        CancellationToken cancellationToken
    )
        where TEntity : EntityBaseCore, new() =>
        CheckDatabaseUniquenessAsync(repository, entity, [], cancellationToken);

    /// <summary>
    /// Asks the repository which UNIQUE constraints the given entity violates and registers the findings as duplicate-value
    /// errors, leaving out the findings on properties whose values could not be carried onto the entity (returns true when
    /// no finding remains).
    /// </summary>
    /// <remarks>
    /// <para>
    /// The same as the overload without <paramref name="uncheckedPropertyNames"/>, except that a finding naming any of those
    /// properties is dropped. The generated <c>ValidateUniqueAsync</c> passes a value-type property with no input (the entity
    /// property is not nullable, so the entity carries the CLR default instead) and a property the edit model does not have:
    /// a constraint over such a property would be checked against a value the user never entered, so its finding means
    /// nothing. The other constraints are still checked, and their findings are registered as usual.
    /// </para>
    /// </remarks>
    /// <param name="repository">The repository used for the check.</param>
    /// <param name="entity">The entity carrying the values to check.</param>
    /// <param name="uncheckedPropertyNames">The properties whose values the entity does not carry; findings naming any of them are dropped.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    protected async Task<bool> CheckDatabaseUniquenessAsync<TEntity, TKey>(
        IRemoteRepositoryCore<TEntity, TKey> repository,
        TEntity entity,
        IReadOnlyCollection<string> uncheckedPropertyNames,
        CancellationToken cancellationToken
    )
        where TEntity : EntityBaseCore, new()
    {
        ArgumentNullException.ThrowIfNull(repository);
        ArgumentNullException.ThrowIfNull(uncheckedPropertyNames);

        if (IsRemoved)
        {
            return true;
        }

        ClearDuplicateErrors(DuplicateErrorSource.Database);
        var generation = _databaseCheckGeneration;

        var violations = await repository
            .CheckUniquenessAsync(entity, cancellationToken)
            .ConfigureAwait(false);

        // The values changed while the query was out, so its findings would land on values it did not check
        if (generation != _databaseCheckGeneration)
        {
            return false;
        }

        var checkedViolations = violations
            .Where(violation =>
                !violation.PropertyNames.Any(name => uncheckedPropertyNames.Contains(name))
            )
            .ToList();

        foreach (var violation in checkedViolations)
        {
            RegisterDuplicateError(
                violation.PropertyNames,
                violation.Message,
                DuplicateErrorSource.Database
            );
        }

        return checkedViolations.Count == 0;
    }

    /// <summary>Writes the confirmed values back to the binding properties and clears the input errors (conversion and missing-required-input).</summary>
    /// <remarks>
    /// Duplicate-value errors are not touched here: they are owned by the uniqueness checks (a value that is a duplicate stays a
    /// duplicate when its display string is rebuilt). Loading a different value into the model clears them, because the checks then
    /// have to run again.
    /// </remarks>
    public void RevertInput() => ExecuteRevert(RevertCore);

    /// <summary>Core logic of RevertInput (concrete classes implement writing back each property and clearing its input error).</summary>
    protected virtual void RevertCore() { }

    /// <summary>Executes an action with the reverting flag set (nesting is counted, so an inner revert does not clear the flag for the outer one).</summary>
    protected void ExecuteRevert(Action action)
    {
        _revertDepth++;

        try
        {
            action();
        }
        finally
        {
            _revertDepth--;
        }
    }

    /// <summary>Executes an action with the loading flag set (called from mapper loads; confirmed-value changes during load do not promote the state to Updated). Nesting is counted, so a load started from a hook does not clear the flag for the outer one.</summary>
    public void ExecuteLoad(Action action)
    {
        BeginLoad();

        try
        {
            action();
        }
        finally
        {
            EndLoad();
        }
    }

    /// <summary>Enters the loading state (the same counter <see cref="ExecuteLoad"/> uses). Every call must be paired with <see cref="EndLoad"/> from a <c>finally</c>.</summary>
    /// <remarks>
    /// It exists so a caller that already has a <c>try</c>/<c>finally</c> of its own - the generated mapper's load, for one -
    /// can mark the load without handing a closure to <see cref="ExecuteLoad"/>.
    /// </remarks>
    internal void BeginLoad() => _loadDepth++;

    /// <summary>Leaves the loading state entered by <see cref="BeginLoad"/>.</summary>
    internal void EndLoad() => _loadDepth--;

    /// <summary>Whether a row edit is in progress (IEditableObject; true between BeginEdit and EndEdit/CancelEdit).</summary>
    private bool _editing;

    /// <summary>Begins a row edit and snapshots the current state (supports canceling DataGrid row edits).</summary>
    public void BeginEdit()
    {
        if (_editing)
        {
            return;
        }

        _editing = true;
        BeginEditCore();
    }

    /// <summary>Commits the row edit. Changes are already applied immediately, so this only clears the editing flag.</summary>
    public void EndEdit()
    {
        if (!_editing)
        {
            return;
        }

        _editing = false;
        EndEditCore();
    }

    /// <summary>Cancels the row edit: the confirmed values and the RowState go back to the snapshot <see cref="BeginEdit"/> took, and the input strings are derived from the restored confirmed values.</summary>
    /// <remarks>
    /// <para>
    /// The input errors are cleared for every property, not only for the ones the canceled edit touched, because rebuilding
    /// the input strings from the restored confirmed values goes through <see cref="RevertInput"/>, which clears each
    /// property's input error unconditionally. A conversion error that was already there when <see cref="BeginEdit"/> ran
    /// therefore disappears as well. The value it complained about is gone from the display in the same step - the input
    /// string is rebuilt from the confirmed value, so the unconvertible text is no longer on screen for the message to refer
    /// to - and it comes back as soon as that text is typed again.
    /// </para>
    /// <para>
    /// The duplicate-value findings do not survive a cancel either, and no check is re-run to replace them: the ones the
    /// database check registered are withdrawn unconditionally - even for a row that was begun and then canceled without a
    /// single change, whose finding was still perfectly valid - and the ones about duplicates among the siblings are left
    /// standing whether or not the restored value still duplicates one. Run the database check and the collection's
    /// <c>Validate</c> again before saving; a finding of either is only ever as current as its last run.
    /// See <see cref="CancelEditCore"/> for the reasoning.
    /// </para>
    /// </remarks>
    public void CancelEdit()
    {
        if (!_editing)
        {
            return;
        }

        _editing = false;
        CancelEditCore();
    }

    /// <summary>Discards an in-progress row edit without restoring the snapshot (called by the mapper before loading).</summary>
    /// <remarks>
    /// A load replaces the confirmed values, so the snapshot <see cref="BeginEdit"/> took no longer describes a state worth
    /// returning to: a <see cref="CancelEdit"/> arriving after the load must not roll the loaded values back to the stale
    /// pre-load edit. Clearing the editing flag is enough - the snapshot storage is overwritten by the next BeginEdit.
    /// </remarks>
    internal void AbandonRowEdit() => _editing = false;

    /// <summary>Core logic of BeginEdit (<see cref="EditModelBaseCore{TSelf}"/> snapshots the confirmed values from the column table; a generated class adds its OnBeginEdit hook).</summary>
    protected virtual void BeginEditCore() { }

    /// <summary>Core logic of EndEdit (does nothing by default; override in a concrete class if needed).</summary>
    protected virtual void EndEditCore() { }

    /// <summary>Core logic of CancelEdit (<see cref="EditModelBaseCore{TSelf}"/> restores the confirmed values from the snapshot it took).</summary>
    protected virtual void CancelEditCore() { }

    /// <summary>
    /// Runs at the end of the restoring load of <see cref="CancelEditCore"/>, before the row state goes back to its snapshot
    /// (only generated code overrides this, to reach its OnCancelEdit partial hook; do not implement manually).
    /// </summary>
    /// <remarks>
    /// The cancel hook is the one hook that has to run in the middle of the sequence - inside the load, so the restored values
    /// do not promote the row to an update target - which is why it is reached through a step of its own where the begin and
    /// commit hooks are simply appended by the generated override.
    /// </remarks>
    protected virtual void OnCancelEditCore() { }
}

/// <summary>Automatic messages for edit models (defaults shared by all edit models). Replacing them at app startup applies to every edit model.</summary>
/// <remarks>
/// Every entry receives the confirmed-value property name (or the list of them) first, so a replacement can single out one
/// column with <c>nameof</c> - <c>propertyName == nameof(CustomerEditModel.CustomerId)</c> - and stop compiling the day that
/// property is renamed or removed. The defaults do not use it: it is material for the replacement, not part of the wording.
/// </remarks>
public static class EditModelMessages
{
    /// <summary>Message for a missing required field (arguments: confirmed-value property name, display name).</summary>
    /// <remarks>The display name is quoted with single quotes, matching the conversion error style ('input value') and the .NET identifier-quoting convention.</remarks>
    public static Func<string, string, string> Required { get; set; } =
        static (propertyName, displayName) => $"'{displayName}' is required.";

    /// <summary>Message for a binding value that cannot be converted (arguments: confirmed-value property name, display name, input value, target type name). The default does not include the display name.</summary>
    public static Func<string, string, string, string, string> ParseFailed { get; set; } =
        static (propertyName, displayName, inputValue, typeName) =>
            $"'{inputValue}' cannot be converted to {typeName}.";

    /// <summary>Combines value object validation errors into a single edit model error message.</summary>
    public static Func<IReadOnlyList<string>, string> JoinValueObjectErrors { get; set; } =
        static errors => string.Join(" / ", errors);

    /// <summary>Message for a value that duplicates another element or another row in the database (arguments: the constraint's member property names and their display names, both in declaration order).</summary>
    /// <remarks>The display names are quoted with single quotes, matching the required-field and conversion error styles.</remarks>
    public static Func<IReadOnlyList<string>, IReadOnlyList<string>, string> DuplicateValue
    {
        get;
        set;
    } = static (propertyNames, displayNames) =>
        $"'{string.Join(", ", displayNames)}' is already used.";
}

/// <summary>Identifies the uniqueness check that found a duplicate-value error, so each check clears only what it registered.</summary>
/// <remarks>
/// The two checks answer different questions and run at different times: the sibling check compares the edit models of a
/// collection with each other, while the database check asks the repository about the rows already stored. Without this
/// distinction, running one of them would discard what the other had just reported.
/// </remarks>
public enum DuplicateErrorSource
{
    /// <summary>The duplicate check among the edit models themselves (<see cref="EditModelCollection{T}.Validate"/> / <see cref="EditModelUniquenessValidator"/>).</summary>
    Siblings,

    /// <summary>The check against the rows already stored in the database (the generated edit model wrapper over the repository's uniqueness check).</summary>
    Database,
}

/// <summary>One UNIQUE constraint declared by an edit model (its name, the properties that make it up, and a compiled accessor for their values).</summary>
/// <remarks>
/// Generated edit models publish their constraints through <see cref="EditModelBaseCore.UniquenessConstraints"/> and
/// <see cref="EditModelUniquenessValidator"/> consumes them. The accessor is generated code, so the check reads no property by reflection.
/// The DB definition itself is described separately by the <c>[UniqueConstraint]</c> attribute on the entity class.
/// </remarks>
public sealed class EditModelUniquenessConstraint
{
    /// <summary>Gets the constraint name (the DDL name, or the synthesized name when the diagram does not set one).</summary>
    public string ConstraintName { get; }

    /// <summary>Gets the confirmed-value property names that make up the constraint (declaration order). The binding properties an error is registered on are derived from them.</summary>
    public IReadOnlyList<string> PropertyNames { get; }

    /// <summary>Gets the accessor that reads the constraint member values of an edit model in a single call (declaration order, matching <see cref="PropertyNames"/>).</summary>
    public Func<EditModelBaseCore, object?[]> GetValues { get; }

    /// <summary>Initializes a new instance with the constraint name, its member property names, and the value accessor.</summary>
    public EditModelUniquenessConstraint(
        string constraintName,
        IReadOnlyList<string> propertyNames,
        Func<EditModelBaseCore, object?[]> getValues
    )
    {
        ConstraintName = constraintName;
        PropertyNames = propertyNames;
        GetValues = getValues;
    }
}

/// <summary>
/// Shared helper that detects values duplicated among edit models by reading the UNIQUE constraints they declare (<see cref="EditModelBaseCore.UniquenessConstraints"/>).
/// </summary>
/// <remarks>
/// It is schema-independent and does not bake in property names (each edit model declares its own constraints). It is called at the
/// end of <see cref="EditModelCollection{T}.Validate"/>, and application code can call it directly for a root-level list. The scope rules match the database check:
/// value tuples that contain a null are out of scope (NULL collision semantics differ per dialect), deletion targets (RowState.Removed) are excluded, and every
/// element of a duplicated group gets the error. The comparison itself is ordinal (structural equality on the CLR values), so a database whose collation is
/// case- or accent-insensitive can still report a duplicate here as distinct - the database check (the repository's CheckUniquenessAsync) has the last word,
/// and checking against rows already stored in the database is its separate concern.
/// </remarks>
public static class EditModelUniquenessValidator
{
    /// <summary>
    /// Detects values duplicated among the given edit models and registers a duplicate-value error on every element of each duplicated group
    /// (returns true when there are no duplicates).
    /// </summary>
    /// <remarks>
    /// The duplicate-value errors registered by the previous call are cleared first, so re-validating never leaves stale errors. Only the findings of this
    /// check are cleared, so violations the database check reported survive. The constraints are read from the
    /// first element that is not a deletion target, so the elements are expected to be of a single edit model type.
    /// </remarks>
    /// <param name="models">The edit models to compare with each other.</param>
    public static bool Validate<T>(IEnumerable<T> models)
        where T : EditModelBaseCore
    {
        ArgumentNullException.ThrowIfNull(models);

        var targets = models.Where(model => !model.IsRemoved).ToList();

        foreach (var model in targets)
        {
            model.ClearDuplicateErrors(DuplicateErrorSource.Siblings);
        }

        return ValidateCleared(targets);
    }

    /// <summary>Body of <see cref="Validate"/> for models whose previous findings of this check are already cleared and that are not deletion targets.</summary>
    /// <remarks>
    /// <c>EditModelCollection.Validate</c> has to clear those findings before it validates each element (a stale one would make
    /// the element look invalid), so it calls this directly rather than having them cleared a second time.
    /// </remarks>
    /// <param name="targets">The edit models to compare with each other, none of them marked for removal.</param>
    internal static bool ValidateCleared<T>(IReadOnlyList<T> targets)
        where T : EditModelBaseCore
    {
        if (targets.Count == 0)
        {
            return true;
        }

        var valid = true;

        foreach (var constraint in targets[0].UniquenessConstraints)
        {
            var groups = new Dictionary<object[], List<T>>(UniquenessKeyComparer.Instance);

            foreach (var model in targets)
            {
                var key = BuildKey(model, constraint);

                // A tuple that contains a null is out of scope (it matches the semantics of the database check).
                if (key is null)
                {
                    continue;
                }

                if (!groups.TryGetValue(key, out var group))
                {
                    groups[key] = group = new List<T>();
                }

                group.Add(model);
            }

            foreach (var group in groups.Values)
            {
                if (group.Count < 2)
                {
                    continue;
                }

                valid = false;

                foreach (var model in group)
                {
                    model.RegisterDuplicateError(
                        constraint.PropertyNames,
                        null,
                        DuplicateErrorSource.Siblings
                    );
                }
            }
        }

        return valid;
    }

    /// <summary>Builds the comparison tuple of the constraint's member values through its accessor (null when any value is null = out of scope).</summary>
    private static object[]? BuildKey(
        EditModelBaseCore model,
        EditModelUniquenessConstraint constraint
    )
    {
        var values = constraint.GetValues(model);

        foreach (var value in values)
        {
            if (value is null)
            {
                return null;
            }
        }

        return values!;
    }

    /// <summary>Structural comparer for the value tuples (byte[] compares by content, and value objects by their overridden equality).</summary>
    private sealed class UniquenessKeyComparer : IEqualityComparer<object[]>
    {
        /// <summary>The shared instance (stateless).</summary>
        public static readonly UniquenessKeyComparer Instance = new();

        /// <summary>Compares two value tuples element by element.</summary>
        public bool Equals(object[]? x, object[]? y)
        {
            if (x is null || y is null)
            {
                return ReferenceEquals(x, y);
            }

            if (x.Length != y.Length)
            {
                return false;
            }

            for (var i = 0; i < x.Length; i++)
            {
                if (!StructuralComparisons.StructuralEqualityComparer.Equals(x[i], y[i]))
                {
                    return false;
                }
            }

            return true;
        }

        /// <summary>Combines the element hash codes of a value tuple.</summary>
        public int GetHashCode(object[] obj)
        {
            var hash = new HashCode();

            foreach (var value in obj)
            {
                hash.Add(StructuralComparisons.StructuralEqualityComparer.GetHashCode(value));
            }

            return hash.ToHashCode();
        }
    }
}

/// <summary>A single validation error in an edit model graph.</summary>
/// <param name="Path">Node position from the root (e.g. empty = root, "SubHeaders[0]", "SubHeaders[0].Records[2]").</param>
/// <param name="Property">Name of the binding property the error is attached to (e.g. BindingTitle).</param>
/// <param name="Message">The error message.</param>
public sealed record EditModelError(string Path, string Property, string Message);

/// <summary>Renders a date or time confirmed value as the input string shown on screen, keeping a sub-second part that the culture's own format would drop.</summary>
/// <remarks>
/// <para>
/// A value whose sub-second part is zero is rendered by its own <c>ToString()</c>, character for character - the culture's
/// format is what the screen has always shown and there is nothing extra to carry. Only a value that does hold a sub-second
/// part is rendered through a pattern that appends it, because otherwise the input string would not describe the value it was
/// derived from: the next commit of that field (its LostFocus re-parses the text through the binding setter) would write the
/// truncated instant back over the stored one. <see cref="TimeOnly"/> is the one type whose own <c>ToString()</c> drops a
/// larger part - the seconds - so its overload keeps that form only for a value on a whole minute.
/// </para>
/// <para>
/// The fraction is written with a literal <c>.</c> and no trailing zeros, whatever the culture's decimal separator is. It has
/// to survive the return trip through the binding setter, which parses with the current culture, and the '.' is what the date
/// and time parsers accept as the fraction mark across cultures.
/// </para>
/// </remarks>
public static class EditModelInputFormat
{
    /// <summary>Time patterns that carry a sub-second part, keyed by the long time pattern they were derived from.</summary>
    /// <remarks>
    /// The key is the pattern text rather than the <see cref="CultureInfo"/>: two CultureInfo instances compare equal by
    /// name alone, so a clone whose <c>LongTimePattern</c> was customized would collapse onto the original's cached entry
    /// and render with the wrong pattern.
    /// </remarks>
    private static readonly ConcurrentDictionary<string, string> _fractionalTimePatterns = new();

    /// <summary>Renders a <see cref="DateTime"/> confirmed value (null becomes an empty string).</summary>
    public static string Format(DateTime? value) =>
        value is not { } resolved ? string.Empty
        : !HasFraction(resolved.Ticks) ? resolved.ToString()
        : resolved.ToString(
            CultureInfo.CurrentCulture.DateTimeFormat.ShortDatePattern
                + " "
                + FractionalTimePattern(CultureInfo.CurrentCulture),
            CultureInfo.CurrentCulture
        );

    /// <summary>Renders a <see cref="DateTimeOffset"/> confirmed value (null becomes an empty string).</summary>
    public static string Format(DateTimeOffset? value) =>
        value is not { } resolved ? string.Empty
        : !HasFraction(resolved.Ticks) ? resolved.ToString()
        : resolved.ToString(
            CultureInfo.CurrentCulture.DateTimeFormat.ShortDatePattern
                + " "
                + FractionalTimePattern(CultureInfo.CurrentCulture)
                + " zzz",
            CultureInfo.CurrentCulture
        );

    /// <summary>Renders a <see cref="TimeSpan"/> confirmed value (null becomes an empty string).</summary>
    /// <remarks>
    /// Nothing is appended: the default format of a <see cref="TimeSpan"/> already writes the sub-second part when there is
    /// one, so the value is lossless as it stands. The overload exists so that every sub-second-capable type is rendered
    /// through the same call.
    /// </remarks>
    public static string Format(TimeSpan? value) => value?.ToString() ?? string.Empty;

    /// <summary>Renders a <see cref="TimeOnly"/> confirmed value (null becomes an empty string).</summary>
    /// <remarks>
    /// Unlike the other types, the own <c>ToString()</c> of a <see cref="TimeOnly"/> writes the short time, which leaves the
    /// seconds out. So only a value on a whole minute keeps that form; a value with seconds is written in the culture's long
    /// time pattern, and a value with a sub-second part in that pattern with the fraction attached. Each is the shortest form
    /// that still shows the whole value, so editing another field never writes back a time cut down to the minute.
    /// </remarks>
    public static string Format(TimeOnly? value) =>
        value is not { } resolved ? string.Empty
        : HasFraction(resolved.Ticks)
            ? resolved.ToString(
                FractionalTimePattern(CultureInfo.CurrentCulture),
                CultureInfo.CurrentCulture
            )
        : resolved.Second != 0 ? resolved.ToLongTimeString()
        : resolved.ToString();

    /// <summary>Whether the tick count carries a part smaller than a second.</summary>
    private static bool HasFraction(long ticks) => ticks % TimeSpan.TicksPerSecond != 0;

    /// <summary>The culture's long time pattern with a sub-second part attached to its seconds.</summary>
    private static string FractionalTimePattern(CultureInfo culture) =>
        _fractionalTimePatterns.GetOrAdd(
            culture.DateTimeFormat.LongTimePattern,
            static pattern => AttachFraction(pattern)
        );

    /// <summary>Inserts a literal-dot, trailing-zero-free sub-second token right after the seconds of a time pattern.</summary>
    /// <remarks>
    /// The scan skips quoted literals and escaped characters, so an 's' that a culture spells out as text is not mistaken
    /// for the seconds token. A pattern that shows no seconds at all is returned unchanged - there is nothing for a fraction
    /// to hang off - and the value is then shown exactly as it was before.
    /// </remarks>
    private static string AttachFraction(string timePattern)
    {
        var quote = '\0';

        for (var index = 0; index < timePattern.Length; index++)
        {
            var character = timePattern[index];

            if (quote != '\0')
            {
                if (character == quote)
                {
                    quote = '\0';
                }

                continue;
            }

            if (character is '\'' or '"')
            {
                quote = character;
                continue;
            }

            if (character == '\\')
            {
                index++;
                continue;
            }

            if (character != 's')
            {
                continue;
            }

            var end = index;

            while (end + 1 < timePattern.Length && timePattern[end + 1] == 's')
            {
                end++;
            }

            return timePattern[..(end + 1)] + "\\.FFFFFFF" + timePattern[(end + 1)..];
        }

        return timePattern;
    }
}

/// <summary>One column of an edit model as data: the two names it is known by, whether input is required, and the accessors the shared checks drive.</summary>
/// <remarks>
/// <para>
/// A generated edit model publishes one of these per column through <see cref="EditModelBaseCore{TSelf}.EditModelColumns"/>, and
/// the required-field check, the input revert, the row-edit snapshot, and the duplicate-error mapping are then written once in
/// the base class instead of once per column in every class. The accessors are compiled lambdas over the real properties, so
/// nothing here is read by reflection and the storage of a column - its confirmed-value field, its input string field - is
/// exactly what it was.
/// </para>
/// <para>
/// The display name is a delegate rather than a string because it is resolved through <c>GeneratedDisplayNames.Resolve</c>,
/// which the application may replace after the table has been built.
/// </para>
/// </remarks>
/// <typeparam name="TModel">The concrete edit model type the accessors read and write.</typeparam>
/// <param name="PropertyName">The confirmed-value property's name (the stable key uniqueness checks and message resolvers switch on).</param>
/// <param name="BindingPropertyName">The input binding property's name (the name errors are registered under).</param>
/// <param name="IsRequired">Whether the missing-required-input check applies to this column.</param>
/// <param name="IsRequiredWhenAdded">Whether the missing-required-input check applies to this column while the row is still <see cref="RowState.Added"/> - a NOT NULL column the repository leaves out of SELECT and UPDATE, which the database rejects if it is inserted empty.</param>
/// <param name="DisplayName">Resolves the display name used in validation messages.</param>
/// <param name="GetValue">Reads the confirmed value.</param>
/// <param name="SetValue">Writes the confirmed value through its internal setter.</param>
/// <param name="ToInput">Derives the on-screen input string from the confirmed value.</param>
/// <param name="SetInput">Writes the derived input string to the binding property.</param>
public sealed record EditModelColumn<TModel>(
    string PropertyName,
    string BindingPropertyName,
    bool IsRequired,
    bool IsRequiredWhenAdded,
    Func<string> DisplayName,
    Func<TModel, object?> GetValue,
    Action<TModel, object?> SetValue,
    Func<TModel, string> ToInput,
    Action<TModel, string> SetInput
)
    where TModel : EditModelBaseCore;

/// <summary>Self-typed layer over <see cref="EditModelBaseCore"/>: the sibling navigation and the owning collection surface in the concrete type, written once.</summary>
/// <remarks>
/// The non-generic <see cref="EditModelBaseCore"/> stays as the type the ownership plumbing references
/// (<see cref="EditModelCollection{T}"/>'s constraint, <see cref="EditModelBaseCore.Owner"/>,
/// <see cref="EditModelBaseCore.ParentModel"/>), so this layer adds only what needs the concrete type. Generated edit
/// models derive from it; the typed parent-model surface stays with them, because the parent is a second type this
/// single type parameter cannot name.
/// </remarks>
/// <typeparam name="TSelf">The concrete edit model type deriving from this class.</typeparam>
public abstract class EditModelBaseCore<TSelf> : EditModelBaseCore
    where TSelf : EditModelBaseCore<TSelf>
{
    /// <summary>Returns the next element after this one in its owning collection (null if not owned or at the end).</summary>
    public new TSelf? GetNext() => (TSelf?)base.GetNext();

    /// <summary>Returns the previous element before this one in its owning collection (null if not owned or at the start).</summary>
    public new TSelf? GetPrevious() => (TSelf?)base.GetPrevious();

    /// <summary>Gets the parent collection this element belongs to (null if not owned).</summary>
    public EditModelCollection<TSelf>? ParentCollection => Owner as EditModelCollection<TSelf>;

    /// <summary>Core reorder logic for the owning collection. Calls Move on the typed collection (used by the MoveTo* methods).</summary>
    protected override void MoveCore(int oldIndex, int newIndex) =>
        ParentCollection?.Move(oldIndex, newIndex);

    /// <summary>Gets this edit model's columns as data (empty by default; a generated edit model overrides it with its static column table).</summary>
    /// <remarks>
    /// It is what makes the required-field check, the input revert, the row-edit snapshot, and the duplicate-error mapping
    /// below shared code: each of them walks this table instead of naming the columns. A handwritten edit model that leaves
    /// it empty simply gets none of those four behaviours, exactly as if it declared no columns.
    /// </remarks>
    protected virtual IReadOnlyList<EditModelColumn<TSelf>> EditModelColumns =>
        Array.Empty<EditModelColumn<TSelf>>();

    /// <summary>This instance seen as the concrete edit model type (the column accessors are typed to it).</summary>
    private TSelf Self => (TSelf)this;

    /// <summary>Checks the columns declared required for missing input, registering and withdrawing only the errors this check owns. Called from Validate; a generated class appends its OnValidate hook.</summary>
    /// <remarks>
    /// <para>
    /// A field that already carries another input error keeps it (<see cref="EditModelBaseCore.SetRequiredError"/> declines to
    /// overwrite), because a value that cannot be converted is the more upstream cause and the one the user has to act on.
    /// </para>
    /// <para>
    /// A column marked <see cref="EditModelColumn{TModel}.IsRequiredWhenAdded"/> is checked only while the row is still
    /// <see cref="RowState.Added"/>: the value is on its way into an INSERT, which the database rejects on a NOT NULL column
    /// that is left empty. Once the row exists, the column is out of scope for UPDATE and an absent value means "keep what is
    /// stored", so the check withdraws what it registered while the row was new.
    /// </para>
    /// </remarks>
    protected override void ValidateSelf()
    {
        var model = Self;

        foreach (var column in EditModelColumns)
        {
            if (!column.IsRequired && !column.IsRequiredWhenAdded)
            {
                continue;
            }

            var applies = column.IsRequired || RowState == RowState.Added;

            if (applies && column.GetValue(model) is null)
            {
                SetRequiredError(
                    column.BindingPropertyName,
                    EditModelMessages.Required(column.PropertyName, column.DisplayName())
                );
            }
            else
            {
                ClearRequiredError(column.BindingPropertyName);
            }
        }
    }

    /// <summary>Writes the confirmed values back to the binding properties and clears the input errors (called from RevertInput; duplicate-value errors belong to the uniqueness checks).</summary>
    protected override void RevertCore()
    {
        var model = Self;

        foreach (var column in EditModelColumns)
        {
            column.SetInput(model, column.ToInput(model));
            SetError(column.BindingPropertyName, null);
        }
    }

    /// <summary>Pre-edit snapshot of the confirmed values, in column order (the array is reused across edits).</summary>
    private object?[]? _valueSnapshot;

    /// <summary>Pre-edit snapshot of the RowState.</summary>
    private RowState _rowStateSnapshot;

    /// <summary>Core logic of BeginEdit. Snapshots each confirmed value and the RowState.</summary>
    protected override void BeginEditCore()
    {
        var model = Self;
        var columns = EditModelColumns;

        if (_valueSnapshot is null || _valueSnapshot.Length != columns.Count)
        {
            _valueSnapshot = new object?[columns.Count];
        }

        for (var i = 0; i < columns.Count; i++)
        {
            _valueSnapshot[i] = columns[i].GetValue(model);
        }

        _rowStateSnapshot = RowState;
    }

    /// <summary>Core logic of CancelEdit. Restores the confirmed values and the RowState from the snapshot, then derives the input strings from them and clears the errors the canceled input left behind.</summary>
    /// <remarks>
    /// <para>
    /// The confirmed values are the source of truth, so they are put back directly rather than rebuilt by re-parsing
    /// the input strings: a display format cannot express everything a value holds - <see cref="System.DateTime"/>
    /// sub-second precision and Kind, for example - so re-parsing would let a canceled edit silently degrade the very
    /// value it was supposed to leave untouched.
    /// </para>
    /// <para>
    /// Restoring the values also withdraws the duplicate-value findings the database check registered, on the reasoning a
    /// confirmed-value setter uses: the value they were reached about is no longer the one the model holds. The setter
    /// cannot do it here, because the restore runs as a load and a load deliberately keeps the setters quiet - so a cancel
    /// would otherwise leave a finding about the discarded value behind and hold <see cref="EditModelBaseCore.Validate"/>
    /// false forever. It is done unconditionally, though, where a setter withdraws them only when the value actually
    /// changes: a cancel does not track whether anything was edited, so a row that was begun and then canceled without a
    /// single change drops a database finding that was still perfectly valid. Run the database check again before saving -
    /// a finding of its is only ever as current as its last run. Only that check's findings are withdrawn, whereas the
    /// findings among the siblings are about the collection as it stands and belong to the next check over it.
    /// </para>
    /// <para>
    /// Leaving them to that check cuts both ways, and nothing here runs it: a cancel that puts back a value which
    /// duplicates a sibling restores the duplicate without restoring the finding about it, just as a cancel that undoes
    /// a duplicate leaves the finding standing. Run the collection's <c>Validate</c> again before saving - the sibling
    /// findings are only ever as current as the last check over the collection.
    /// </para>
    /// <para>
    /// Deriving the input strings clears the input error of every property, so a conversion error that predates the
    /// <see cref="EditModelBaseCore.BeginEdit"/> of this row is cleared along with the ones the canceled edit produced. The
    /// unconvertible text goes away in the same step, since the input string is rebuilt from the restored confirmed value,
    /// and typing it again brings the error back.
    /// </para>
    /// </remarks>
    protected override void CancelEditCore()
    {
        BeginLoad();

        try
        {
            var model = Self;
            var columns = EditModelColumns;
            var snapshot = _valueSnapshot;

            if (snapshot is not null)
            {
                for (var i = 0; i < columns.Count; i++)
                {
                    columns[i].SetValue(model, snapshot[i]);
                }
            }

            // Derive the input strings from the restored confirmed values (RevertCore also clears the errors the
            // canceled input produced).
            ExecuteRevert(RevertCore);
            ClearDuplicateErrors(DuplicateErrorSource.Database);
            OnCancelEditCore();
        }
        finally
        {
            EndLoad();
        }

        RowState = _rowStateSnapshot;
    }

    /// <inheritdoc />
    /// <remarks>
    /// The names are mapped to their binding properties through the column table, so a duplicate is reported on every
    /// property that makes up the constraint. A name the table does not know (a user-defined check may report one) still
    /// contributes its display name to the message, but has no binding property to attach the error to; when none of the
    /// names can be mapped - an empty list included - the error is registered on the model itself.
    /// </remarks>
    public override void RegisterDuplicateError(
        IReadOnlyList<string> propertyNames,
        string? message,
        DuplicateErrorSource source = DuplicateErrorSource.Siblings
    )
    {
        var displayNames = new List<string>(propertyNames.Count);
        var targets = new List<string>(propertyNames.Count);

        foreach (var propertyName in propertyNames)
        {
            var column = FindColumn(propertyName);

            if (column is null)
            {
                displayNames.Add(propertyName);
                continue;
            }

            displayNames.Add(column.DisplayName());
            targets.Add(column.BindingPropertyName);
        }

        var resolved = message ?? EditModelMessages.DuplicateValue(propertyNames, displayNames);

        if (targets.Count == 0)
        {
            SetDuplicateError(string.Empty, resolved, source);
            return;
        }

        foreach (var target in targets)
        {
            SetDuplicateError(target, resolved, source);
        }
    }

    /// <summary>Finds the column with the specified confirmed-value property name (null when this edit model has no such column).</summary>
    private EditModelColumn<TSelf>? FindColumn(string propertyName)
    {
        foreach (var column in EditModelColumns)
        {
            if (string.Equals(column.PropertyName, propertyName, StringComparison.Ordinal))
            {
                return column;
            }
        }

        return null;
    }
}

/// <summary>Collection of edit models. Tracks existing elements removed via Remove as deletion targets.</summary>
/// <remarks>
/// Existing elements removed via Remove / RemoveAt are marked Removed and set aside (new = Added elements are not set aside because they do not exist in the database).
/// Clear is a full on-screen wipe with no deletion tracking (it also resets the set-aside items). Use Remove when the deletion should be saved.
/// </remarks>
public sealed partial class EditModelCollection<T> : ObservableCollection<T>
    where T : EditModelBaseCore
{
    /// <summary>Holding list for deletion targets (Removed) removed via Remove, each with the state it had before the removal.</summary>
    private readonly List<RemovedItem> _removed = new();

    /// <summary>A deletion target together with the change state it had before it was removed (restored when the very same instance is added back).</summary>
    private readonly record struct RemovedItem(T Item, RowState PriorState);

    /// <summary>Backing field for the parent model that holds this collection as a child.</summary>
    private EditModelBaseCore? _ownerModel;

    /// <summary>Gets or sets the parent model that holds this collection as a child (set by the owning edit model). Propagates to every element's ParentModel when set.</summary>
    internal EditModelBaseCore? OwnerModel
    {
        get => _ownerModel;
        set
        {
            _ownerModel = value;
            foreach (var item in this)
            {
                item.SetParentModel(value);
            }
        }
    }

    /// <summary>Creates an empty collection.</summary>
    public EditModelCollection() { }

    /// <summary>Creates the collection with the given edit models as initial elements (no deletion tracking).</summary>
    public EditModelCollection(IEnumerable<T> items)
        : base(items)
    {
        // base(items) adds directly to the internal list without going through InsertItem, so set the owner here.
        foreach (var item in this)
        {
            item.Owner = this;
            item.SetParentModel(_ownerModel);
        }
    }

    /// <summary>Gets the deletion targets (Removed) taken out via Remove, in the order they were removed.</summary>
    /// <remarks>The result is a snapshot rather than a live view of the tracking list.</remarks>
    public IReadOnlyList<T> RemovedItems => _removed.Select(entry => entry.Item).ToList();

    /// <summary>Gets a value indicating whether any element (or its cascade children) has changes, or deletion-tracked items exist.</summary>
    public bool HasChanges => _removed.Count > 0 || this.Any(item => item.HasGraphChanges());

    /// <summary>Inserts an element. Sets this collection as the element's owner and raises position property change notifications.</summary>
    /// <remarks>
    /// Adding back an instance that was removed earlier cancels the deletion instead of saving a delete and an insert of the very
    /// same row: the element leaves the tracking list and its change state returns to what it was before the removal.
    /// </remarks>
    protected override void InsertItem(int index, T item)
    {
        UntrackRemoval(item);
        item.Owner = this;
        item.SetParentModel(_ownerModel);
        base.InsertItem(index, item);
        item.RaiseParentCollectionChanged();
        NotifyPositionsChanged();
    }

    /// <summary>Takes an element out (Remove / RemoveAt). Existing elements are set aside as Removed; new elements are discarded.</summary>
    protected override void RemoveItem(int index)
    {
        var removed = this[index];
        TrackRemoval(removed);
        removed.Owner = null;
        removed.SetParentModel(null);
        base.RemoveItem(index);
        removed.RaiseParentCollectionChanged();
        removed.RaisePositionChanged();
        NotifyPositionsChanged();
    }

    /// <summary>Replaces an element via indexer assignment. The existing element being replaced is set aside as Removed (and a replacement that was removed earlier is taken back off the deletion list).</summary>
    protected override void SetItem(int index, T item)
    {
        var replaced = this[index];
        TrackRemoval(replaced);
        UntrackRemoval(item);
        replaced.Owner = null;
        replaced.SetParentModel(null);
        item.Owner = this;
        item.SetParentModel(_ownerModel);
        base.SetItem(index, item);
        replaced.RaiseParentCollectionChanged();
        replaced.RaisePositionChanged();
        item.RaiseParentCollectionChanged();
        NotifyPositionsChanged();
    }

    /// <summary>Moves an element (reorders only, no deletion tracking). Raises position property change notifications after the move.</summary>
    protected override void MoveItem(int oldIndex, int newIndex)
    {
        // base.MoveItem calls the non-virtual Remove/Insert of Collection&lt;T&gt;, so it does not go through the deletion-tracking overrides in this class.
        base.MoveItem(oldIndex, newIndex);
        NotifyPositionsChanged();
    }

    /// <summary>Full on-screen wipe. No deletion tracking; set-aside deletion targets are restored to their pre-removal state and released.</summary>
    /// <remarks>
    /// Releasing the tracking list alone would leave the set-aside elements marked Removed with nothing left to undo it:
    /// adding such an instance back afterwards can no longer be matched by the tracking list, so it would sit in the
    /// collection as a deletion target and be silently deleted on the next save.
    /// </remarks>
    protected override void ClearItems()
    {
        var cleared = new List<T>(this);

        foreach (var item in this)
        {
            item.Owner = null;
            item.SetParentModel(null);
        }

        // Restore before releasing the tracking list, the same way cancelling a single removal does.
        foreach (var entry in _removed)
        {
            entry.Item.RowState = entry.PriorState;
        }

        _removed.Clear();
        base.ClearItems();

        foreach (var item in cleared)
        {
            item.RaiseParentCollectionChanged();
            item.RaisePositionChanged();
        }
    }

    /// <summary>Clears deletion tracking after a save is confirmed. The set-aside elements become Added, subtree and all.</summary>
    /// <remarks>
    /// The stored rows these elements described are gone (a graph delete cascades over the descendants), so an instance
    /// that is added back afterwards means a new graph: marking the whole subtree Added here makes that re-add insert it
    /// (marking only the root would insert the parent and silently drop the children - a graph save does not write
    /// Unchanged rows). Releasing the tracking list with the elements still Removed would recreate the untracked-Removed
    /// shape <see cref="ClearItems"/> warns about - the re-added instance could no longer be matched by the tracking
    /// list, so it would sit in the collection as a deletion target and never be saved.
    /// </remarks>
    public void AcceptRemoved()
    {
        foreach (var entry in _removed)
        {
            entry.Item.MarkSubtreeAdded();
        }

        _removed.Clear();
    }

    /// <summary>Marks every element's subtree for insertion and releases this collection's deletion tracking (building block of <see cref="EditModelBaseCore.MarkSubtreeAdded"/>).</summary>
    internal void MarkSubtreeAdded()
    {
        foreach (var item in this)
        {
            item.MarkSubtreeAdded();
        }

        AcceptRemoved();
    }

    /// <summary>Resets all elements (and cascade children) to the unchanged state after a save is confirmed, and also clears deletion tracking.</summary>
    /// <param name="includeChildren">True to recursively accept changes on each element's cascade children as well.</param>
    /// <remarks>
    /// Elements marked for deletion (<c>IsRemoved</c>, left in the collection by MarkRemoved) leave the collection here:
    /// the save has just deleted their rows, so accepting them as ordinary elements would resurrect a deleted row on
    /// screen (Unchanged) and hand it to the next save. They go out before the acceptance loop, without deletion
    /// tracking, and stay Removed - the instance no longer describes a stored row.
    /// </remarks>
    public void AcceptChanges(bool includeChildren = true)
    {
        RemoveAcceptedDeletions();

        foreach (var item in this)
        {
            item.AcceptChanges(includeChildren);
        }

        AcceptRemoved();
    }

    /// <summary>Accepts a save of the entities built from this collection, as the children of <paramref name="parentEntity"/>.</summary>
    /// <remarks>
    /// The save takes a child it deleted out of its parent's cascade collection, so a removed element whose entity is still
    /// among the parent entity's children was skipped by a save hook and stays pending.
    /// </remarks>
    /// <param name="parentEntity">The saved entity of the model that holds this collection.</param>
    internal void AcceptSaved(EntityBaseCore parentEntity)
    {
        var kept = new HashSet<EntityBaseCore>(
            parentEntity.EnumerateCascadeChildren(),
            ReferenceEqualityComparer.Instance
        );

        AcceptSaved(static _ => true, kept.Contains);
    }

    /// <summary>Accepts a save of the entities built from this collection.</summary>
    /// <remarks>
    /// An element whose recorded entity is not part of the save (<paramref name="isSaved"/>) is left as it is. A new row marked
    /// for deletion leaves the collection; a removed element whose deletion was saved leaves it too (an element set aside by
    /// Remove becomes an insertion target, as <see cref="AcceptRemoved"/> describes), while one whose deletion a save hook
    /// skipped (<paramref name="deletionSkipped"/>) stays pending. Every other saved element accepts its own outcome.
    /// </remarks>
    /// <param name="isSaved">Whether an entity was part of the save.</param>
    /// <param name="deletionSkipped">Whether the deletion of an entity was skipped.</param>
    internal void AcceptSaved(
        Func<EntityBaseCore, bool> isSaved,
        Func<EntityBaseCore, bool> deletionSkipped
    )
    {
        bool DeletionSaved(T item) =>
            item.AppliedEntity is { } entity && isSaved(entity) && !deletionSkipped(entity);

        var changed = false;

        _rangeOperationDepth++;

        try
        {
            for (var i = Count - 1; i >= 0; i--)
            {
                var item = this[i];

                if (!item.IsDiscardedNewRow && !(item.IsRemoved && DeletionSaved(item)))
                {
                    continue;
                }

                item.ForgetApplied();
                item.Owner = null;
                item.SetParentModel(null);
                // base.RemoveItem skips the deletion-tracking override: there is no stored row left to delete
                base.RemoveItem(i);
                item.RaiseParentCollectionChanged();
                item.RaisePositionChanged();
                changed = true;
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        foreach (var item in this.ToList())
        {
            if (!item.IsRemoved && item.AppliedEntity is { } entity && isSaved(entity))
            {
                item.AcceptSavedApplied();
            }
        }

        for (var i = _removed.Count - 1; i >= 0; i--)
        {
            var item = _removed[i].Item;

            if (DeletionSaved(item))
            {
                item.ForgetApplied();
                item.MarkSubtreeAdded();
                _removed.RemoveAt(i);
            }
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Takes the elements whose deletion was just saved (IsRemoved) out of the collection without deletion tracking (they stay Removed).</summary>
    /// <remarks>Each element raises its own CollectionChanged (and its own position notification) as usual; the position property notifications for the remaining elements are raised once at the end, the same way the range operations do.</remarks>
    private void RemoveAcceptedDeletions()
    {
        var changed = false;

        _rangeOperationDepth++;

        try
        {
            for (var i = Count - 1; i >= 0; i--)
            {
                if (!this[i].IsRemoved)
                {
                    continue;
                }

                var item = this[i];
                item.Owner = null;
                item.SetParentModel(null);
                // base.RemoveItem skips the deletion-tracking override: the deletion is already saved, so the
                // element must not enter the tracking list (AcceptRemoved would turn it into an insertion target).
                base.RemoveItem(i);
                item.RaiseParentCollectionChanged();
                item.RaisePositionChanged();
                changed = true;
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Validates all elements in the collection (and their cascade children). Validates every element and returns true only if all are valid.</summary>
    /// <param name="includeChildren">True to cascade validation to each element's children as well.</param>
    /// <remarks>
    /// Elements marked for deletion (<c>IsRemoved</c>, left in the collection by MarkRemoved) are skipped: only their keys take
    /// part in the save, so their input cannot block it. The duplicate check among the siblings leaves them out as well.
    /// </remarks>
    public bool Validate(bool includeChildren = true)
    {
        var valid = true;
        var targets = new List<T>(Count);

        foreach (var item in this)
        {
            // A row that is about to be deleted takes no part in the checks (its input is not saved), so leave its errors as they are.
            if (item.IsRemoved)
            {
                continue;
            }

            // Clear this check's duplicate-value errors from the previous run first: they are re-registered below, and leaving
            // them would make this element look invalid even after the duplication was resolved. Findings of the database check
            // are left alone (they are cleared and re-registered by that check instead).
            item.ClearDuplicateErrors(DuplicateErrorSource.Siblings);
            targets.Add(item);

            // Do not short-circuit, so that errors are registered for every element.
            if (!item.Validate(includeChildren))
            {
                valid = false;
            }
        }

        // Detect values duplicated among the elements themselves (the UNIQUE constraints declared on the edit model class).
        // It runs after every element has been validated, so the duplicate-value errors are registered on top of the fresh per-element errors.
        // The elements' previous findings were cleared above, so the check starts from them as they are.
        if (!EditModelUniquenessValidator.ValidateCleared(targets))
        {
            valid = false;
        }

        return valid;
    }

    /// <summary>Collects validation errors of all elements in the collection, prefixed with their positions ([i]) (call Validate beforehand).</summary>
    /// <param name="includeChildren">True to recursively collect from each element's cascade children as well.</param>
    /// <remarks>Elements marked for deletion contribute nothing, matching what <see cref="Validate"/> leaves out.</remarks>
    public IEnumerable<EditModelError> CollectErrors(bool includeChildren = true)
    {
        var errors = new List<EditModelError>();

        for (var i = 0; i < Count; i++)
        {
            this[i].CollectErrors($"[{i}]", includeChildren, errors);
        }

        return errors;
    }

    /// <summary>Moves the specified element to the specified position in the collection (reorders only, no deletion tracking). Returns true if moved.</summary>
    public bool MoveTo(T item, int newIndex)
    {
        var oldIndex = IndexOf(item);
        if (oldIndex < 0 || oldIndex == newIndex)
        {
            return false;
        }

        Move(oldIndex, newIndex);
        return true;
    }

    /// <summary>Appends the specified elements to the end.</summary>
    /// <remarks>Each element raises its own CollectionChanged as usual; the position property notifications for the whole collection are raised once at the end instead of once per insertion (per-insertion broadcasts grow quadratically with the element count). When the operation throws partway (a faulting enumerator, say), the elements already inserted keep their CollectionChanged events but the final broadcast is not raised - the position properties still read correctly, and the next collection change refreshes their bindings.</remarks>
    public void AddRange(IEnumerable<T> items)
    {
        var changed = false;

        _rangeOperationDepth++;

        try
        {
            foreach (var item in items)
            {
                Add(item);
                changed = true;
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Inserts the specified elements at the specified position.</summary>
    /// <remarks>Each element raises its own CollectionChanged as usual; the position property notifications for the whole collection are raised once at the end instead of once per insertion (per-insertion broadcasts grow quadratically with the element count). When the operation throws partway (a faulting enumerator, say), the elements already inserted keep their CollectionChanged events but the final broadcast is not raised - the position properties still read correctly, and the next collection change refreshes their bindings.</remarks>
    public void InsertRange(int index, IEnumerable<T> items)
    {
        var changed = false;

        _rangeOperationDepth++;

        try
        {
            foreach (var item in items)
            {
                Insert(index++, item);
                changed = true;
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Removes all elements (existing elements are tracked as Removed). Use Clear for an untracked on-screen wipe.</summary>
    /// <remarks>Elements are removed from the front, so <see cref="RemovedItems"/> keeps the order they had in the collection. Each element raises its own CollectionChanged (and its own position notification) as usual; the position property notifications for the remaining elements are raised once at the end instead of once per removal. When the operation throws partway, the removals already made keep their events but the final broadcast is not raised - the position properties still read correctly, and the next collection change refreshes their bindings.</remarks>
    public void RemoveAll()
    {
        var changed = Count > 0;

        _rangeOperationDepth++;

        try
        {
            while (Count > 0)
            {
                RemoveAt(0);
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Removes the elements in the specified range (existing elements are tracked as Removed).</summary>
    /// <remarks>Each element raises its own CollectionChanged (and its own position notification) as usual; the position property notifications for the remaining elements are raised once at the end instead of once per removal. When the operation throws partway, the removals already made keep their events but the final broadcast is not raised - the position properties still read correctly, and the next collection change refreshes their bindings.</remarks>
    public void RemoveRange(int index, int count)
    {
        if (index < 0 || index > Count)
        {
            throw new ArgumentOutOfRangeException(
                nameof(index),
                "The start position is outside the bounds of the collection."
            );
        }

        // Compared as Count - index (index is already within 0..Count), because index + count can overflow and pass the check
        if (count < 0 || count > Count - index)
        {
            throw new ArgumentOutOfRangeException(
                nameof(count),
                "The specified range is outside the bounds of the collection."
            );
        }

        var changed = count > 0;

        _rangeOperationDepth++;

        try
        {
            for (var i = 0; i < count; i++)
            {
                RemoveAt(index);
            }
        }
        finally
        {
            _rangeOperationDepth--;
        }

        if (changed)
        {
            NotifyPositionsChanged();
        }
    }

    /// <summary>Depth of range operations in progress. While positive, the whole-collection position broadcasts are suppressed and the outermost operation raises one broadcast at the end (a nested range operation started from a CollectionChanged handler coalesces into it). Position property values stay correct throughout, because they are computed from the collection on read.</summary>
    private int _rangeOperationDepth;

    /// <summary>Notifies all elements of position property changes (IndexInParent / IsFirstInParent / IsLastInParent). Range operations suppress the per-mutation broadcast and raise it once when they finish.</summary>
    private void NotifyPositionsChanged()
    {
        if (_rangeOperationDepth > 0)
        {
            return;
        }

        foreach (var item in this)
        {
            item.RaisePositionChanged();
        }
    }

    /// <summary>Sets aside a removed element as a deletion target (new = unsaved elements are not set aside).</summary>
    private void TrackRemoval(T item)
    {
        if (item.IsAdded)
        {
            return;
        }

        // Capture the state before marking the removal, so adding the very same instance back can restore it.
        var priorState = item.RowState;
        item.MarkRemoved();

        if (!_removed.Any(entry => ReferenceEquals(entry.Item, item)))
        {
            _removed.Add(new RemovedItem(item, priorState));
        }
    }

    /// <summary>Cancels the deletion tracking of an element that is being put back into the collection and restores the state it had before the removal.</summary>
    private void UntrackRemoval(T item)
    {
        var tracked = _removed.FindIndex(entry => ReferenceEquals(entry.Item, item));

        if (tracked < 0)
        {
            return;
        }

        item.RowState = _removed[tracked].PriorState;
        _removed.RemoveAt(tracked);
    }
}

/// <summary>Base class providing the skeleton common to converting between entities and edit models (creation, the load sequence, and collection conversion).</summary>
/// <remarks>
/// Derived classes implement only what needs the concrete types: the column copying in each direction
/// (<see cref="ApplyToEntity"/>, <see cref="LoadColumns"/>), the cascade children and the post-load hook
/// (<see cref="CompleteLoad"/>), and the two post-creation hooks. Everything that composes them - the order of the load,
/// the loading state it runs under, creation from an edit model, collection conversion - is written once here.
/// </remarks>
public abstract class MapperBaseCore<TEntity, TEditModel>
    where TEntity : EntityBaseCore, new()
    where TEditModel : EditModelBaseCore, new()
{
    /// <summary>Creates a new TEntity with initial values set (it will be an insertion target on save).</summary>
    public TEntity CreateEntity()
    {
        var entity = new TEntity();
        entity.MarkAdded();
        AfterEntityCreated(entity);
        return entity;
    }

    /// <summary>Called just after a new TEntity is created (only generated code overrides this, to reach its OnEntityCreated partial hook; do not implement manually).</summary>
    /// <param name="entity">The entity that was created.</param>
    protected virtual void AfterEntityCreated(TEntity entity) { }

    /// <summary>Creates a new TEditModel from a TEntity.</summary>
    /// <param name="entity">The entity whose values are loaded.</param>
    public TEditModel CreateEditModel(TEntity entity)
    {
        var editModel = new TEditModel();
        ApplyToEditModel(entity, editModel);
        AfterEditModelCreated(editModel);
        return editModel;
    }

    /// <summary>Called just after a new TEditModel is created and loaded (only generated code overrides this, to reach its OnEditModelCreated partial hook; do not implement manually).</summary>
    /// <param name="editModel">The edit model that was created.</param>
    protected virtual void AfterEditModelCreated(TEditModel editModel) { }

    /// <summary>Applies a TEntity's values to an existing TEditModel (lossless load).</summary>
    /// <remarks>
    /// <para>
    /// Loading is lossless: the confirmed values are copied straight from the entity instead of being rebuilt by parsing
    /// the on-screen input strings, so nothing that the display format cannot express (sub-second precision of a
    /// DateTime, its Kind, and so on) is dropped. The input strings are then derived from the confirmed values.
    /// Binary columns are copied defensively, so editing the loaded model never reaches into the entity's array. The
    /// defensive copy belongs to this direction alone: <see cref="ApplyToEntity"/> assigns the confirmed values across as
    /// they are, so the array an entity receives on the way to being saved is the edit model's own - saving hands the
    /// buffer over rather than duplicating it, and writing into it afterwards is writing into both.
    /// </para>
    /// <para>
    /// The whole sequence runs in the edit model's loading state, where a confirmed-value change does not promote the row
    /// to an update target; the row state is taken from the source entity once the load is over (loaded = Unchanged,
    /// new = Added).
    /// </para>
    /// <para>
    /// Child collections are rebuilt rather than merged: the previous collection instances are replaced by new ones, so
    /// anything held against them is dropped along with them - a selected item, a scroll position or any other view state
    /// bound to the old instance, and the removals the old collection was tracking for the next save. A row edit in
    /// progress on the model itself (IEditableObject) is abandoned for the same reason: its snapshot predates the load,
    /// so a CancelEdit arriving afterwards is a no-op instead of rolling the loaded values back. Load into an edit
    /// model that has pending edits only when discarding them is what is meant.
    /// </para>
    /// </remarks>
    /// <param name="entity">The entity whose values are loaded.</param>
    /// <param name="editModel">The edit model to load the values into.</param>
    public void ApplyToEditModel(TEntity entity, TEditModel editModel)
    {
        // A row edit in progress is abandoned, not canceled: its snapshot predates this load, so a CancelEdit
        // arriving later must not roll the loaded values back to the stale pre-load edit.
        editModel.AbandonRowEdit();
        editModel.ForgetApplied();
        editModel.BeginLoad();

        try
        {
            LoadColumns(entity, editModel);

            // Derive the on-screen input strings from the confirmed values just loaded and clear stale conversion errors.
            editModel.RevertInput();

            // The values the uniqueness checks looked at are gone, so their findings go too (RevertInput only owns the input errors).
            editModel.ClearDuplicateErrors();
            CompleteLoad(entity, editModel);
        }
        finally
        {
            editModel.EndLoad();
        }

        // The edit model's state is based on the source entity (loaded = Unchanged, new = Added).
        editModel.RowState = entity.RowState;
    }

    /// <summary>Copies the entity's column values into the edit model's confirmed values (the first half of the load, before the input strings are derived).</summary>
    /// <param name="entity">The entity whose values are loaded.</param>
    /// <param name="editModel">The edit model to load the values into.</param>
    protected abstract void LoadColumns(TEntity entity, TEditModel editModel);

    /// <summary>Copies a saved entity's column values into the edit model (the read-back of <see cref="AcceptSaved(TEditModel, TEntity)"/>; the default is <see cref="LoadColumns"/>).</summary>
    /// <param name="entity">The entity that was saved.</param>
    /// <param name="editModel">The edit model to read the values into.</param>
    protected virtual void LoadSavedColumns(TEntity entity, TEditModel editModel) =>
        LoadColumns(entity, editModel);

    /// <summary>Accepts the outcome of saving <paramref name="entity"/>, built from <paramref name="editModel"/> by this mapper, into the edit model graph.</summary>
    /// <remarks>
    /// <para>
    /// Call it after a successful save, in place of <see cref="EditModelBaseCore.AcceptChanges"/>. A row the save wrote is read
    /// back into its edit model, which becomes Unchanged: the new version the database assigned, the values it computed, and
    /// the values a save hook set (a key, an audit column) reach the edit model, so the next save updates the right row with
    /// the right version. A row a save hook skipped keeps its state, so the next save tries it again. A deleted child leaves
    /// its collection, and a child whose deletion a hook skipped stays pending. A deleted root stays Removed; a deletion of the
    /// root that a hook skipped cannot be told apart from a deleted one.
    /// </para>
    /// <para>
    /// The cascade children are matched by the entities this mapper built for them, not by position: the save takes a deleted
    /// child out of its collection. The read-back copies the columns only - child collections are kept (the selection on
    /// screen stays), and the load hooks do not run.
    /// </para>
    /// </remarks>
    /// <param name="editModel">The edit model the entity was built from.</param>
    /// <param name="entity">The entity that was saved.</param>
    public void AcceptSaved(TEditModel editModel, TEntity entity)
    {
        ArgumentNullException.ThrowIfNull(editModel);
        ArgumentNullException.ThrowIfNull(entity);

        editModel.AcceptSaved(entity, () => ReadBackSaved(entity, editModel));
    }

    /// <summary>Accepts the outcome of saving <paramref name="entities"/>, built from <paramref name="editModels"/> by <see cref="CreateEntities"/>, into the collection.</summary>
    /// <remarks>
    /// Each element is matched with the entity this mapper built for it, and accepted as
    /// <see cref="AcceptSaved(TEditModel, TEntity)"/> does. An element whose entity is not among <paramref name="entities"/> is
    /// left as it is. A removed element whose entity was saved is taken as deleted, the same way a deleted root is.
    /// </remarks>
    /// <param name="editModels">The collection the entities were built from.</param>
    /// <param name="entities">The entities that were saved.</param>
    public void AcceptSaved(EditModelCollection<TEditModel> editModels, IEnumerable<TEntity> entities)
    {
        ArgumentNullException.ThrowIfNull(editModels);
        ArgumentNullException.ThrowIfNull(entities);

        var saved = new HashSet<EntityBaseCore>(entities, ReferenceEqualityComparer.Instance);
        editModels.AcceptSaved(saved.Contains, static _ => false);
    }

    /// <summary>Records <paramref name="entity"/> as the entity built from <paramref name="editModel"/> (the generated <see cref="ApplyToEntity"/> calls it, so <see cref="AcceptSaved(TEditModel, TEntity)"/> can find the children's entities).</summary>
    /// <param name="editModel">The edit model the entity was built from.</param>
    /// <param name="entity">The entity built from it.</param>
    protected void RememberApplied(TEditModel editModel, TEntity entity) =>
        editModel.RememberApplied(entity, () => ReadBackSaved(entity, editModel));

    /// <summary>Returns whether a cascade child is left out of the entity graph: a new row marked for deletion always is, and a removed child is unless <paramref name="includeRemoved"/>.</summary>
    /// <param name="child">The child edit model.</param>
    /// <param name="includeRemoved">Whether removed children take part (true for saving).</param>
    protected static bool IsLeftOutOfSave(EditModelBaseCore child, bool includeRemoved) =>
        child.IsDiscardedNewRow || (!includeRemoved && child.IsRemoved);

    /// <summary>Reads a saved entity's column values back into the edit model, in the loading state, and derives the input strings again.</summary>
    private void ReadBackSaved(TEntity entity, TEditModel editModel)
    {
        editModel.AbandonRowEdit();
        editModel.BeginLoad();

        try
        {
            LoadSavedColumns(entity, editModel);
            editModel.RevertInput();
            editModel.ClearDuplicateErrors();
        }
        finally
        {
            editModel.EndLoad();
        }
    }

    /// <summary>Finishes the load once the input strings have been derived: builds the cascade children and runs the post-load hook.</summary>
    /// <param name="entity">The entity whose values are loaded.</param>
    /// <param name="editModel">The edit model being loaded.</param>
    protected abstract void CompleteLoad(TEntity entity, TEditModel editModel);

    /// <summary>Returns the edit model's confirmed value, or throws when the column holds no input.</summary>
    /// <remarks>
    /// A confirmed value is nullable on the edit model even where the entity's column is not, because the model has to hold
    /// input that is still incomplete. Applying it to an entity is where that has to be resolved, and an absent value is an
    /// error rather than something to write as null. The one exception is a removed row: it takes part in the save through
    /// its key alone, so the generated ApplyToEntity skips its absent non-key values instead of calling this (the key still
    /// goes through here - a delete without its key would target the wrong row).
    /// </remarks>
    /// <param name="value">The confirmed value.</param>
    /// <param name="propertyName">The property's name, used in the exception message.</param>
    protected static T Required<T>(T? value, string propertyName)
        where T : class =>
        value ?? throw new InvalidOperationException($"{propertyName} has no input value.");

    /// <summary>Returns the edit model's confirmed value, or throws when the column holds no input.</summary>
    /// <param name="value">The confirmed value.</param>
    /// <param name="propertyName">The property's name, used in the exception message.</param>
    protected static T Required<T>(T? value, string propertyName)
        where T : struct =>
        value ?? throw new InvalidOperationException($"{propertyName} has no input value.");

    /// <summary>Applies the TEditModel's confirmed values to an existing TEntity (destructive update). Column copying is implemented by derived classes.</summary>
    /// <param name="editModel">The edit model whose confirmed values are applied.</param>
    /// <param name="entity">The existing entity to apply the values to.</param>
    /// <param name="includeRemoved">Whether to also restore and apply deletion-tracked (Removed) items - collection elements and a single cascade child alike (false leaves a removed single child out as null). This argument is required: pass true for saving, false for report display and similar.</param>
    public abstract void ApplyToEntity(TEditModel editModel, TEntity entity, bool includeRemoved);

    /// <summary>Creates a new TEntity with initial values set and the TEditModel's confirmed values applied.</summary>
    /// <param name="editModel">The edit model whose confirmed values are applied.</param>
    /// <param name="includeRemoved">Whether to also restore and apply deletion-tracked (Removed) items - collection elements and a single cascade child alike (false leaves a removed single child out as null). This argument is required: pass true for saving, false for report display and similar.</param>
    public TEntity CreateEntity(TEditModel editModel, bool includeRemoved)
    {
        var entity = CreateEntity();
        ApplyToEntity(editModel, entity, includeRemoved);
        return entity;
    }

    /// <summary>Creates a list of TEntity from an EditModelCollection of TEditModel.</summary>
    /// <param name="editModels">The collection of edit models to create from.</param>
    /// <param name="includeRemoved">Whether to also restore and include deletion-tracked (Removed) items - collection elements and a single cascade child alike (false leaves a removed single child out as null). This argument is required: pass true for saving, false for report display and similar.</param>
    public List<TEntity> CreateEntities(
        EditModelCollection<TEditModel> editModels,
        bool includeRemoved
    )
    {
        // A new row marked for deletion has no stored row, so it takes no part in the save
        var entities = editModels
            .Where(editModel => !editModel.IsDiscardedNewRow)
            .Select(editModel => CreateEntity(editModel, includeRemoved))
            .ToList();

        if (includeRemoved)
        {
            entities.AddRange(
                editModels.RemovedItems.Select(removed => CreateEntity(removed, includeRemoved))
            );
        }

        return entities;
    }

    /// <summary>Creates a TEditModel for new input (built from an insertion-target entity).</summary>
    public TEditModel CreateEditModel()
    {
        var entity = CreateEntity();
        var editModel = CreateEditModel(entity);
        return editModel;
    }

    /// <summary>Creates an EditModelCollection of TEditModel from a sequence of TEntity.</summary>
    public EditModelCollection<TEditModel> CreateEditModels(IEnumerable<TEntity> entities)
    {
        return new EditModelCollection<TEditModel>(entities.Select(entity => CreateEditModel(entity)));
    }
}

/// <summary>Base of every generated edit model, and the extension point for them. Members added to a partial declaration of this type reach all of them at once.</summary>
/// <typeparam name="TSelf">The concrete edit model type deriving from this class.</typeparam>
public abstract partial class EditModelBase<TSelf> : EditModelBaseCore<TSelf>
    where TSelf : EditModelBase<TSelf> { }

/// <summary>Edit model for on-screen editing of the documents table.</summary>
public partial class DocumentEditModel : EditModelBase<DocumentEditModel>
{
    // Each column keeps two representations: the confirmed value and the on-screen input string (conversion errors are held by the error dictionary).
