    /// <summary>
    /// Checks this edit model's confirmed values against the database through the repository and registers duplicate-value errors (returns true when there are no violations).
    /// </summary>
    /// <remarks>
    /// The duplicate-value errors registered by the previous call are cleared first, so re-checking never leaves stale errors (only the ones this check registered:
    /// what the check among the siblings reported stays). Rows that share the primary key are excluded,
    /// so the same call is correct for both insert and update (a model whose key is not set yet excludes nothing). The result is advisory only: the definitive guarantee is the database's own UNIQUE constraint (TOCTOU).
    /// Every confirmed value is copied onto the entity, so a custom check sees the whole row. A constraint that includes a property with no input that the entity cannot leave empty (a value type, or a text or binary column that is not nullable),
    /// or a property the edit model does not have, is not checked (the entity would carry a value nobody entered); the other constraints are.
    /// When a confirmed value is edited, the model is reloaded, or another check starts while the call is awaiting, what the query found is about values the model no longer holds:
    /// nothing is registered and the call returns false, meaning that the current values were not confirmed unique. Run the check again after the last edit, before saving.
    /// The errors are registered after the await, which puts them on a thread pool thread rather than the caller's, and ErrorsChanged fires there too.
    /// A WPF binding marshals that back to the UI thread by itself, so the ordinary case needs nothing; a subscriber that updates UI state directly has to marshal it at the call site.
    /// </remarks>
    /// <param name="repository">The repository used for the check.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public Task<bool> ValidateUniqueAsync(
        IDocumentRemoteRepository repository,
        CancellationToken cancellationToken = default
    )
    {
        // Properties whose values the entity cannot carry: findings that name any of them are dropped.
        var uncheckedProperties = new List<string>();

        if (DocumentId is null)
        {
            uncheckedProperties.Add(nameof(DocumentEntity.DocumentId));
        }

        if (Title is null)
        {
            uncheckedProperties.Add(nameof(DocumentEntity.Title));
        }

        if (IsPublished is null)
        {
            uncheckedProperties.Add(nameof(DocumentEntity.IsPublished));
        }

        if (Thumb is null)
        {
            uncheckedProperties.Add(nameof(DocumentEntity.Thumb));
        }

        var entity = new DocumentEntity();

        if (DocumentId is { } resolvedDocumentId)
        {
            entity.DocumentId = resolvedDocumentId;
        }

        if (Title is { } resolvedTitle)
        {
            entity.Title = resolvedTitle;
        }

        if (IsPublished is { } resolvedIsPublished)
        {
            entity.IsPublished = resolvedIsPublished;
        }

        if (Payload is { } resolvedPayload)
        {
            entity.Payload = resolvedPayload;
        }

        if (Thumb is { } resolvedThumb)
        {
            entity.Thumb = resolvedThumb;
        }

        if (Checksum is { } resolvedChecksum)
        {
            entity.Checksum = resolvedChecksum;
        }

        if (RowVer is { } resolvedRowVer)
        {
            entity.RowVer = resolvedRowVer;
        }

        return CheckDatabaseUniquenessAsync(repository, entity, uncheckedProperties, cancellationToken);
    }

