/// <summary>Base of every generated mapper, and the extension point for them. Members added to a partial declaration of this type reach all of them at once.</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TEditModel">The edit model type.</typeparam>
public abstract partial class MapperBase<TEntity, TEditModel> : MapperBaseCore<TEntity, TEditModel>
    where TEntity : EntityBaseCore, new()
    where TEditModel : EditModelBaseCore, new() { }

/// <summary>Converts between DocumentEntity and DocumentEditModel.</summary>
public sealed partial class DocumentMapper
    : MapperBase<DocumentEntity, DocumentEditModel>
{
    /// <inheritdoc />
    protected override void AfterEntityCreated(DocumentEntity entity) =>
        OnEntityCreated(entity);

    /// <summary>Called just after a new DocumentEntity is created (set initial values via a partial implementation).</summary>
    /// <remarks>Every conversion creates a fresh entity, so this also fires when an existing edit model is converted (<c>CreateEntity(editModel, …)</c>), and the RowState at this point is always Added - the edit model's state is transferred later, at the end of the column copy.</remarks>
    partial void OnEntityCreated(DocumentEntity entity);

    /// <inheritdoc />
    protected override void AfterEditModelCreated(DocumentEditModel editModel) =>
        OnEditModelCreated(editModel);

    /// <summary>Called just after a new DocumentEditModel is created (after loading) (set initial values via a partial implementation; branch on IsAdded to target new models only).</summary>
    partial void OnEditModelCreated(DocumentEditModel editModel);

    /// <inheritdoc />
    public override void ApplyToEntity(
        DocumentEditModel editModel,
        DocumentEntity entity,
        bool includeRemoved
    )
    {
        entity.DocumentId = Required(editModel.DocumentId, nameof(editModel.DocumentId));

        // A removed row takes part in the save through its key alone, so an absent value is skipped instead of enforced.
        if (!editModel.IsRemoved || editModel.Title is not null)
        {
            entity.Title = Required(editModel.Title, nameof(editModel.Title));
        }

        // A removed row takes part in the save through its key alone, so an absent value is skipped instead of enforced.
        if (!editModel.IsRemoved || editModel.IsPublished is not null)
        {
            entity.IsPublished = Required(editModel.IsPublished, nameof(editModel.IsPublished));
        }

        // This column is left out of SELECT and UPDATE, so an absent input keeps the entity's current value:
        // the unfetched state stays as it is and the update leaves the stored blob untouched.
        if (editModel.Payload is not null)
        {
            entity.Payload = editModel.Payload;
        }

        // This column is left out of SELECT and UPDATE, so an absent input keeps the entity's current value:
        // the unfetched state stays as it is and the update leaves the stored blob untouched.
        if (editModel.Thumb is not null)
        {
            entity.Thumb = editModel.Thumb;
        }

        entity.Checksum = editModel.Checksum;

        // The database generates this column, so an absent input keeps the entity's current value.
        if (editModel.RowVer is not null)
        {
            entity.RowVer = editModel.RowVer;
        }

        // Transfer the RowState raised on the edit model by confirmed-value changes as-is (no state is created here).
        entity.RowState = editModel.RowState;
        entity.DocumentNotes = new DocumentNoteMapper().CreateEntities(editModel.DocumentNotes, includeRemoved);
        RememberApplied(editModel, entity);
        OnEntityApplied(editModel, entity);
    }

    /// <summary>Called after the DocumentEditModel's confirmed values are applied to the DocumentEntity (save additional properties via a partial implementation).</summary>
    partial void OnEntityApplied(DocumentEditModel editModel, DocumentEntity entity);

    /// <inheritdoc />
    protected override void LoadColumns(DocumentEntity entity, DocumentEditModel editModel)
    {
        editModel.DocumentId = entity.DocumentId;
        editModel.Title = entity.IsAdded && entity.Title is "" ? null : entity.Title;
        editModel.IsPublished = entity.IsPublished;
        editModel.Payload = (byte[]?)entity.Payload?.Clone();
        editModel.Thumb = (byte[]?)entity.Thumb?.Clone();
        editModel.Checksum = entity.IsAdded && entity.Checksum is [] ? null : (byte[]?)entity.Checksum?.Clone();
        editModel.RowVer = (byte[]?)entity.RowVer?.Clone();
    }

    /// <inheritdoc />
    protected override void CompleteLoad(DocumentEntity entity, DocumentEditModel editModel)
    {
        editModel.DocumentNotes = new DocumentNoteMapper().CreateEditModels(entity.DocumentNotes);
        OnEditModelLoaded(entity, editModel);
    }

    /// <summary>Called after the default load into the DocumentEditModel (load additional properties via a partial implementation).</summary>
    partial void OnEditModelLoaded(DocumentEntity entity, DocumentEditModel editModel);
}

